SELECT MAX(`Free Meal Count (K-12)` / `Enrollment (K-12)`)  FROM frpm  WHERE `County Name` = 'Alameda';
SELECT `Percent (%) Eligible Free (Ages 5-17)` FROM `frpm` WHERE `School Type` = 'Continuation' ORDER BY `Percent (%) Eligible Free (Ages 5-17)` ASC LIMIT 3;
SELECT s.`Zip` FROM `schools` s JOIN `frpm` f ON s.`CDSCode` = f.`CDSCode` WHERE f.`Charter School (Y/N)` = 1   AND f.`District Name` = 'Fresno County Office of Education';
SELECT s.`MailStreet` FROM `schools` s JOIN `frpm` f ON s.`CDSCode` = f.`CDSCode` ORDER BY f.`FRPM Count (K-12)` DESC LIMIT 1;
SELECT s.Phone FROM schools s JOIN frpm f ON s.CDSCode = f.CDSCode WHERE f.`Charter School (Y/N)` = 1   AND s.OpenDate > '2000-01-01';
SELECT COUNT(*)  FROM satscores s  JOIN schools sc ON s.cds = sc.CDSCode  WHERE s.AvgScrMath > 400 AND sc.Virtual = 'F';
SELECT s.School FROM schools s JOIN satscores ss ON s.CDSCode = ss.cds WHERE ss.NumTstTakr > 500 AND s.Magnet = 1;
SELECT s.Phone FROM schools s JOIN satscores ss ON s.CDSCode = ss.cds WHERE ss.NumGE1500 = (SELECT MAX(NumGE1500) FROM satscores);
SELECT s.NumTstTakr FROM satscores s JOIN frpm f ON s.cds = f.CDSCode WHERE f.`FRPM Count (K-12)` = (SELECT MAX(`FRPM Count (K-12)`) FROM frpm)
SELECT COUNT(*)  FROM satscores s JOIN schools sch ON s.cds = sch.CDSCode WHERE s.AvgScrMath > 560 AND sch.FundingType = 'Charter';
SELECT t1.`FRPM Count (Ages 5-17)` FROM `frpm` AS t1 JOIN `satscores` AS t2 ON t1.`CDSCode` = t2.`cds` ORDER BY t2.`AvgScrRead` DESC LIMIT 1;
SELECT `CDSCode` FROM `frpm` WHERE `Enrollment (K-12)` + `Enrollment (Ages 5-17)` > 500;
SELECT MAX(`Free Meal Count (Ages 5-17)` / `Enrollment (Ages 5-17)`)  FROM frpm  JOIN satscores ON frpm.CDSCode = satscores.cds  WHERE CAST(satscores.NumGE1500 AS REAL) / satscores.NumTstTakr > 0.3;
SELECT s.Phone FROM schools s JOIN satscores ss ON s.CDSCode = ss.cds ORDER BY CAST(ss.NumGE1500 AS REAL) / ss.NumTstTakr DESC LIMIT 3;
SELECT s.NCESSchool FROM frpm f JOIN schools s ON f.CDSCode = s.CDSCode ORDER BY f.`Enrollment (Ages 5-17)` DESC LIMIT 5;
SELECT s.District FROM schools s JOIN satscores ss ON s.CDSCode = ss.cds WHERE s.StatusType = 'Active' GROUP BY s.District ORDER BY AVG(ss.AvgScrRead) DESC LIMIT 1;
SELECT COUNT(*)  FROM satscores s JOIN schools sch ON s.cds = sch.CDSCode WHERE sch.County = 'Alameda' AND s.NumTstTakr < 100;
SELECT `sname`, `CharterNum`, RANK() OVER (ORDER BY `AvgScrWrite` DESC) AS rank FROM `satscores` JOIN `schools` ON `satscores`.`cds` = `schools`.`CDSCode` WHERE `AvgScrWrite` > 499 AND `CharterNum` IS NOT NULL;
SELECT COUNT(*)  FROM schools s  JOIN satscores ss ON s.CDSCode = ss.cds  WHERE s.County = 'Fresno'    AND s.FundingType = 'Directly Funded'    AND ss.NumTstTakr <= 250;
SELECT s.Phone FROM schools s JOIN satscores ss ON s.CDSCode = ss.cds ORDER BY ss.AvgScrMath DESC LIMIT 1;
SELECT COUNT(*)  FROM frpm  WHERE `County Name` = 'Amador'    AND `Low Grade` = '9'    AND `High Grade` = '12';
SELECT COUNT(*)  FROM frpm  WHERE `County Name` = 'Los Angeles'    AND `Free Meal Count (K-12)` > 500    AND `FRPM Count (K-12)` < 700;
SELECT s.`School` FROM `schools` s JOIN `satscores` ss ON s.`CDSCode` = ss.`cds` WHERE s.`County` = 'Contra Costa' ORDER BY ss.`NumTstTakr` DESC LIMIT 1;
SELECT      frpm.`School Name`,     schools.`Street` FROM      frpm JOIN      schools ON frpm.`CDSCode` = schools.`CDSCode` WHERE      ABS(frpm.`Enrollment (K-12)` - frpm.`Enrollment (Ages 5-17)`) > 30;
SELECT f.`School Name` FROM `frpm` f JOIN `satscores` ss ON f.`CDSCode` = ss.`cds` WHERE (f.`Free Meal Count (K-12)` / f.`Enrollment (K-12)`) > 0.1   AND ss.`NumGE1500` >= 1500;
SELECT s.School, f.`Charter Funding Type` FROM schools s JOIN satscores sat ON s.CDSCode = sat.cds JOIN frpm f ON s.CDSCode = f.CDSCode WHERE s.County = 'Riverside' GROUP BY s.School, f.`Charter Funding Type` HAVING AVG(sat.AvgScrMath) > 400;
SELECT      s.`School`,     s.`Street`,     s.`City`,     s.`State`,     s.`Zip` FROM      `schools` s JOIN      `frpm` f ON s.`CDSCode` = f.`CDSCode` WHERE      s.`County` = 'Monterey'      AND f.`High Grade` >= '09'     AND f.`FRPM Count (Ages 5-17)` > 800;
SELECT      s.School AS `School Name`,     ss.AvgScrWrite AS `Average Score in Writing`,     s.Phone AS `Communication Number` FROM      schools s JOIN      satscores ss ON s.CDSCode = ss.cds WHERE      s.OpenDate > '1991-12-31' OR s.ClosedDate < '2000-01-01';
SELECT s.School, s.DOCType FROM schools s JOIN frpm f ON s.CDSCode = f.CDSCode WHERE (f.`Enrollment (K-12)` - f.`Enrollment (Ages 5-17)`) > (     SELECT AVG(f2.`Enrollment (K-12)` - f2.`Enrollment (Ages 5-17)`)     FROM frpm f2     JOIN schools s2 ON f2.CDSCode = s2.CDSCode     WHERE s2.FundingType = 'Locally Funded' ) AND s.FundingType = 'Locally Funded';
SELECT `OpenDate`  FROM `schools`  JOIN `frpm` ON `schools`.`CDSCode` = `frpm`.`CDSCode`  ORDER BY `frpm`.`Enrollment (K-12)` DESC  LIMIT 1;
SELECT `City` FROM `schools` s JOIN `frpm` f ON s.`CDSCode` = f.`CDSCode` ORDER BY `Enrollment (K-12)` ASC LIMIT 5;
SELECT `Percent (%) Eligible Free (K-12)` FROM `frpm` ORDER BY `Enrollment (K-12)` DESC LIMIT 2 OFFSET 9;
SELECT CAST(`FRPM Count (K-12)` AS REAL) / `Enrollment (K-12)` AS `Percent (%) Eligible FRPM (K-12)` FROM `frpm` JOIN `schools` ON `frpm`.`CDSCode` = `schools`.`CDSCode` WHERE `schools`.`SOC` = '66'    AND `Enrollment (K-12)` > 0    AND `FRPM Count (K-12)` IS NOT NULL    AND `Enrollment (K-12)` IS NOT NULL ORDER BY `FRPM Count (K-12)` DESC LIMIT 5;
SELECT s.Website, s.School FROM schools s JOIN frpm f ON s.CDSCode = f.CDSCode WHERE f.`Free Meal Count (Ages 5-17)` BETWEEN 1900 AND 2000;
SELECT `Free Meal Count (Ages 5-17)` / `Enrollment (Ages 5-17)`  FROM `frpm`  JOIN `schools` ON `frpm`.`CDSCode` = `schools`.`CDSCode`  WHERE `schools`.`AdmFName1` = 'Kacey' AND `schools`.`AdmLName1` = 'Gibson';
SELECT s.`AdmEmail1` FROM `schools` s JOIN `frpm` f ON s.`CDSCode` = f.`CDSCode` WHERE f.`Charter School (Y/N)` = 1 ORDER BY f.`Enrollment (K-12)` ASC LIMIT 1;
SELECT      COALESCE(s.`AdmFName1`, s.`AdmFName2`, s.`AdmFName3`) AS FirstName,     COALESCE(s.`AdmLName1`, s.`AdmLName2`, s.`AdmLName3`) AS LastName FROM `satscores` sat JOIN `schools` s ON sat.`cds` = s.`CDSCode` ORDER BY sat.`NumGE1500` DESC LIMIT 1;
SELECT s.Street, s.City, s.Zip, s.State FROM schools s JOIN satscores ss ON s.CDSCode = ss.cds ORDER BY CAST(ss.NumGE1500 AS REAL) / ss.NumTstTakr ASC LIMIT 1;
SELECT s.Website FROM schools s JOIN satscores ss ON s.CDSCode = ss.cds WHERE s.County = 'Los Angeles' AND ss.NumTstTakr BETWEEN 2000 AND 3000;
SELECT AVG(t1.`NumTstTakr`)  FROM `satscores` AS t1  JOIN `schools` AS t2 ON t1.`cds` = t2.`CDSCode`  WHERE t2.`County` = 'Fresno' AND strftime('%Y', t2.`OpenDate`) = '1980';
SELECT s.Phone FROM schools s JOIN satscores ss ON s.CDSCode = ss.cds WHERE s.District = 'Fresno Unified' ORDER BY ss.AvgScrRead ASC LIMIT 1;
SELECT s.School FROM schools s JOIN satscores ss ON s.CDSCode = ss.cds WHERE s.Virtual = 'F' AND ss.AvgScrRead IS NOT NULL AND ss.cds IN (     SELECT cds     FROM (         SELECT ss2.cds,                ROW_NUMBER() OVER (PARTITION BY s2.County ORDER BY ss2.AvgScrRead DESC) AS rn         FROM schools s2         JOIN satscores ss2 ON s2.CDSCode = ss2.cds         WHERE s2.Virtual = 'F' AND ss2.AvgScrRead IS NOT NULL     ) ranked     WHERE ranked.rn <= 5 )
SELECT `Educational Option Type` FROM `frpm` INNER JOIN `satscores` ON `frpm`.`CDSCode` = `satscores`.`cds` WHERE `satscores`.`AvgScrMath` IS NOT NULL ORDER BY `satscores`.`AvgScrMath` DESC LIMIT 1
SELECT AVG(satscores.AvgScrMath), schools.County FROM satscores JOIN schools ON satscores.cds = schools.CDSCode ORDER BY (satscores.AvgScrMath + satscores.AvgScrRead + satscores.AvgScrWrite) LIMIT 1;
SELECT AVG(t1.AvgScrWrite) AS avg_writing_score, t3.City FROM satscores t1 JOIN schools t3 ON t1.cds = t3.CDSCode WHERE t1.cds = (     SELECT cds     FROM satscores     WHERE NumGE1500 IS NOT NULL     ORDER BY NumGE1500 DESC     LIMIT 1 );
SELECT s.School, ss.AvgScrWrite FROM schools s JOIN satscores ss ON s.CDSCode = ss.cds WHERE s.AdmFName1 = 'Ricci' AND s.AdmLName1 = 'Ulrich';
SELECT s.`School`, f.`Enrollment (K-12)` FROM `schools` s JOIN `frpm` f ON s.`CDSCode` = f.`CDSCode` WHERE s.`DOC` = '31' ORDER BY f.`Enrollment (K-12)` DESC LIMIT 1;
SELECT COUNT(*) / 12.0  FROM schools  WHERE County = 'Alameda'    AND DOC = '52'    AND strftime('%Y', OpenDate) = '1980';
SELECT    CAST(SUM(CASE WHEN s.DOC = '54' THEN 1 ELSE 0 END) AS REAL) /    NULLIF(SUM(CASE WHEN s.DOC = '52' THEN 1 ELSE 0 END), 0) AS ratio FROM schools s WHERE s.County = 'Orange';
SELECT `County`, `School`, `ClosedDate` FROM `schools` WHERE `StatusType` = 'Closed' AND `County` IN (     SELECT `County`     FROM `schools`     WHERE `StatusType` = 'Closed'     GROUP BY `County`     ORDER BY COUNT(*) DESC     LIMIT 1 )
SELECT s.`MailStreet`, s.`School` FROM `schools` s JOIN `satscores` ss ON s.`CDSCode` = ss.`cds` ORDER BY ss.`AvgScrMath` DESC LIMIT 1 OFFSET 6;
SELECT s.MailStreet, s.School FROM schools s JOIN satscores ss ON s.CDSCode = ss.cds WHERE ss.AvgScrRead = (SELECT MIN(AvgScrRead) FROM satscores WHERE AvgScrRead IS NOT NULL)
SELECT COUNT(*)  FROM satscores s  JOIN schools sc ON s.cds = sc.CDSCode  WHERE (s.AvgScrRead + s.AvgScrMath + s.AvgScrWrite) >= 1500  AND sc.MailCity = 'Lakeport';
SELECT SUM(satscores.NumTstTakr) FROM satscores JOIN schools ON satscores.cds = schools.CDSCode WHERE schools.MailCity = 'Fresno';
SELECT `School`, `MailZip` FROM `schools` WHERE `AdmFName1` = 'Avetik' AND `AdmLName1` = 'Atoian';
SELECT CAST(COUNT(CASE WHEN `MailState` = 'CA' AND `County` = 'Colusa' THEN 1 END) AS REAL) / COUNT(CASE WHEN `MailState` = 'CA' AND `County` = 'Humboldt' THEN 1 END)  FROM `schools`;
SELECT COUNT(*)  FROM schools  WHERE MailState = 'CA' AND City = 'San Joaquin' AND StatusType = 'Active';
SELECT s.Phone, s.Ext FROM schools s JOIN satscores ss ON s.CDSCode = ss.cds ORDER BY ss.AvgScrWrite DESC LIMIT 1 OFFSET 332;
SELECT `Phone`, `Ext`, `School` FROM `schools` WHERE `Zip` = '95203-3704';
SELECT s.Website FROM schools s WHERE (s.AdmFName1 = 'Mike' AND s.AdmLName1 = 'Larson')     OR (s.AdmFName1 = 'Dante' AND s.AdmLName1 = 'Alvarez')    OR (s.AdmFName2 = 'Mike' AND s.AdmLName2 = 'Larson')     OR (s.AdmFName2 = 'Dante' AND s.AdmLName2 = 'Alvarez')    OR (s.AdmFName3 = 'Mike' AND s.AdmLName3 = 'Larson')     OR (s.AdmFName3 = 'Dante' AND s.AdmLName3 = 'Alvarez');
SELECT `Website` FROM `schools` WHERE `Virtual` = 'P' AND `Charter` = 1 AND `County` = 'San Joaquin';
SELECT COUNT(*)  FROM schools  WHERE Charter = 1    AND City = 'Hickman'    AND DOC = '52';
SELECT COUNT(*)  FROM schools s JOIN frpm f ON s.CDSCode = f.CDSCode WHERE s.County = 'Los Angeles'    AND s.Charter = 0    AND (f.`Free Meal Count (K-12)` * 100 / f.`Enrollment (K-12)`) < 0.18;
SELECT      s.School,     s.City,     s.AdmFName1 AS AdmFName,     s.AdmLName1 AS AdmLName FROM      schools s WHERE      s.Charter = 1      AND s.CharterNum = '00D2'     AND s.AdmFName1 IS NOT NULL      AND s.AdmLName1 IS NOT NULL  UNION ALL  SELECT      s.School,     s.City,     s.AdmFName2 AS AdmFName,     s.AdmLName2 AS AdmLName FROM      schools s WHERE      s.Charter = 1      AND s.CharterNum = '00D2'     AND s.AdmFName2 IS NOT NULL      AND s.AdmLName2 IS NOT NULL  UNION ALL  SELECT      s.School,     s.City,     s.AdmFName3 AS AdmFName,     s.AdmLName3 AS AdmLName FROM      schools s WHERE      s.Charter = 1      AND s.CharterNum = '00D2'     AND s.AdmFName3 IS NOT NULL      AND s.AdmLName3 IS NOT NULL;
SELECT COUNT(*)  FROM schools  WHERE MailCity = 'Hickman' AND CharterNum = '00D4';
SELECT    (COUNT(CASE WHEN `Charter Funding Type` = 'Locally Funded' THEN 1 END) * 100.0 / COUNT(*)) AS percentage FROM frpm WHERE `County Name` = 'Santa Clara';
SELECT COUNT(*)  FROM schools  WHERE FundingType = 'Directly Funded'    AND County = 'Stanislaus'    AND OpenDate BETWEEN '2000-01-01' AND '2005-12-31';
SELECT SUM(CASE WHEN `StatusType` = 'Community College District' AND `ClosedDate` LIKE '1989%' AND `City` = 'San Francisco' THEN 1 ELSE 0 END) AS total_closures FROM `schools`;
SELECT `County` FROM `schools` WHERE `SOC` = '11' AND `ClosedDate` BETWEEN '1980-01-01' AND '1989-12-31' GROUP BY `County` ORDER BY COUNT(*) DESC LIMIT 1;
SELECT `NCESDist` FROM `schools` WHERE `SOC` = '31';
SELECT COUNT(*)  FROM schools  WHERE County = 'Alpine'    AND StatusType IN ('Active', 'Closed')    AND School LIKE '%District Community Day School%';
SELECT `District Code` FROM `frpm` WHERE `CDSCode` IN (     SELECT `CDSCode`     FROM `schools`     WHERE `City` = 'Fresno' AND `Magnet` = 0 )
SELECT `Enrollment (Ages 5-17)` FROM `frpm` f JOIN `schools` s ON f.`CDSCode` = s.`CDSCode` WHERE s.`EdOpsCode` = 'SSS'   AND s.`City` = 'Fremont'   AND f.`Academic Year` = '2014-2015';
SELECT `FRPM Count (Ages 5-17)` FROM `frpm` f JOIN `schools` s ON f.`CDSCode` = s.`CDSCode` WHERE s.`School` = 'Youth Authority School' AND s.`MailStreet` = 'PO Box 1040';
SELECT `Low Grade`  FROM `frpm`  JOIN `schools` ON `frpm`.`CDSCode` = `schools`.`CDSCode`  WHERE `schools`.`EdOpsCode` = 'SPECON' AND `schools`.`NCESDist` = '0613360';
SELECT `Educational Option Type`, `School Name` FROM `frpm` WHERE `County Code` = '37' AND `NSLP Provision Status` = 'Breakfast Provision 2';
SELECT s.City FROM schools s JOIN frpm f ON s.CDSCode = f.CDSCode WHERE f.`County Name` = 'Merced'   AND f.`Educational Option Type` = 'Lunch Provision 2'   AND f.`Low Grade` = '9'   AND f.`High Grade` = '12'   AND s.EILCode = 'HS';
SELECT s.School, f.`Percent (%) Eligible FRPM (Ages 5-17)` FROM schools s JOIN frpm f ON s.CDSCode = f.CDSCode WHERE s.County = 'Los Angeles' AND f.`Low Grade` = 'K' AND f.`High Grade` = '9';
SELECT `GSserved`  FROM `schools`  WHERE `City` = 'Adelanto'  GROUP BY `GSserved`  ORDER BY COUNT(*) DESC  LIMIT 1;
SELECT County, COUNT(*) AS school_count FROM schools WHERE County IN ('San Diego', 'Santa Barbara') AND Virtual = 'F' GROUP BY County ORDER BY school_count DESC LIMIT 1;
SELECT `School Type`, `School Name`, `Latitude` FROM `frpm` f JOIN `schools` s ON f.`CDSCode` = s.`CDSCode` ORDER BY `Latitude` DESC LIMIT 1;
SELECT s.City, f.`Low Grade`, s.School FROM schools s JOIN frpm f ON s.CDSCode = f.CDSCode WHERE s.State = 'CA' AND s.Latitude IS NOT NULL ORDER BY s.Latitude ASC LIMIT 1;
SELECT `GSoffered`  FROM `schools`  ORDER BY ABS(`Longitude`) DESC  LIMIT 1;
SELECT      COUNT(*) AS num_schools_multiple_provision,     COUNT(DISTINCT s.City) AS num_cities,     s.City,     COUNT(*) AS schools_per_city FROM schools s JOIN frpm f ON s.CDSCode = f.CDSCode WHERE s.Magnet = 1      AND s.GSoffered = 'K-8'      AND f.`NSLP Provision Status` = 'Multiple Provision Types' GROUP BY s.City;
SELECT AdmFName1, District FROM schools WHERE AdmFName1 IS NOT NULL GROUP BY AdmFName1, District ORDER BY COUNT(*) DESC LIMIT 2;
SELECT `Percent (%) Eligible Free (K-12)`, `District Code` FROM `frpm` f JOIN `schools` s ON f.`CDSCode` = s.`CDSCode` WHERE s.`AdmFName1` = 'Alusine' OR s.`AdmFName2` = 'Alusine' OR s.`AdmFName3` = 'Alusine';
SELECT s.AdmLName1, s.District, s.County, s.School FROM schools s WHERE s.CharterNum = '40';
SELECT `AdmEmail1`, `AdmEmail2`, `AdmEmail3` FROM `schools` WHERE `County` = 'San Bernardino'   AND `District` = 'San Bernardino City Unified'   AND `OpenDate` BETWEEN '2009-01-01' AND '2010-12-31'   AND `SOC` = '62'   AND `DOC` = '54';
SELECT s.`AdmEmail1`, s.`School` FROM `schools` s JOIN `satscores` ss ON s.`CDSCode` = ss.`cds` WHERE ss.`NumGE1500` = (SELECT MAX(`NumGE1500`) FROM `satscores`) LIMIT 1;
SELECT COUNT(*)  FROM account a  JOIN district d ON a.district_id = d.district_id  WHERE a.frequency = 'POPLATEK PO OBRATU'  AND d.A3 = 'East Bohemia';
SELECT COUNT(*)  FROM account a  JOIN district d ON a.district_id = d.district_id  WHERE d.A3 = 'Prague';
SELECT    CASE      WHEN AVG(A12) > AVG(A13) THEN '1995'     ELSE '1996'   END AS higher_year FROM district;
SELECT COUNT(*)  FROM district d JOIN client c ON d.district_id = c.district_id WHERE c.gender = 'F' AND d.A11 > 6000 AND d.A11 < 10000;
SELECT COUNT(*)  FROM client c  JOIN district d ON c.district_id = d.district_id  WHERE c.gender = 'M' AND d.A3 = 'North Bohemia' AND d.A11 > 8000;
SELECT      a.account_id,     (SELECT MAX(d.A11) FROM district d) - (SELECT MIN(d.A11) FROM district d) AS gap FROM      account a JOIN      disp d ON a.account_id = d.account_id JOIN      client c ON d.client_id = c.client_id JOIN      district di ON c.district_id = di.district_id WHERE      c.gender = 'F'      AND c.birth_date = (SELECT MIN(c2.birth_date) FROM client c2 WHERE c2.gender = 'F')     AND di.A11 = (SELECT MIN(di2.A11) FROM district di2                    JOIN client c3 ON di2.district_id = c3.district_id                    WHERE c3.gender = 'F'                    AND c3.birth_date = (SELECT MIN(c4.birth_date) FROM client c4 WHERE c4.gender = 'F'));
SELECT a.account_id FROM account a JOIN disp d ON a.account_id = d.account_id JOIN client c ON d.client_id = c.client_id JOIN district dt ON c.district_id = dt.district_id WHERE c.birth_date = (SELECT MAX(birth_date) FROM client) ORDER BY dt.A11 DESC LIMIT 1;
SELECT COUNT(*)  FROM account a JOIN disp d ON a.account_id = d.account_id WHERE a.frequency = 'POPLATEK TYDNE' AND d.type = 'OWNER';
SELECT c.client_id FROM client c JOIN disp d ON c.client_id = d.client_id JOIN account a ON d.account_id = a.account_id WHERE d.type = 'DISPONENT' AND a.frequency = 'POPLATEK PO OBRATU';
SELECT a.account_id FROM account a JOIN loan l ON a.account_id = l.account_id WHERE l.status = 'A'    AND strftime('%Y', l.date) = '1997'   AND a.frequency = 'POPLATEK TYDNE' ORDER BY l.amount ASC LIMIT 1;
SELECT a.account_id FROM account a JOIN loan l ON a.account_id = l.account_id WHERE l.duration > 12   AND l.status = 'A'   AND strftime('%Y', a.date) = '1993' ORDER BY l.amount DESC LIMIT 1;
SELECT COUNT(*)  FROM client c  JOIN district d ON c.district_id = d.district_id  WHERE c.gender = 'F'    AND c.birth_date < '1950-01-01'    AND d.A2 = 'Sokolov';
SELECT account_id FROM trans WHERE date LIKE '1995-%' AND date = (     SELECT MIN(date)     FROM trans     WHERE date LIKE '1995-%' );
SELECT DISTINCT a.account_id FROM account a JOIN trans t ON a.account_id = t.account_id WHERE a.date < '1997-01-01' AND t.amount > 3000;
SELECT c.client_id FROM client c JOIN disp d ON c.client_id = d.client_id JOIN card ca ON d.disp_id = ca.disp_id WHERE ca.issued = '1994-03-03';
SELECT a.date FROM account a JOIN trans t ON a.account_id = t.account_id WHERE t.amount = 840 AND t.date = '1998-10-14';
SELECT a.district_id FROM loan l JOIN account a ON l.account_id = a.account_id WHERE l.date = '1994-08-25' AND l.status = 'A';
SELECT MAX(t.amount) FROM trans t JOIN account a ON t.account_id = a.account_id JOIN disp d ON a.account_id = d.account_id JOIN card c ON d.disp_id = c.disp_id WHERE c.issued = '1996-10-21';
SELECT c.gender FROM client c JOIN account a ON c.client_id = (     SELECT d.client_id     FROM disp d     WHERE d.account_id = a.account_id AND d.type = 'OWNER'     LIMIT 1 ) WHERE a.district_id = (     SELECT district_id     FROM district     ORDER BY A11 DESC     LIMIT 1 ) ORDER BY c.birth_date ASC LIMIT 1;
SELECT t.amount  FROM trans t  JOIN account a ON t.account_id = a.account_id  WHERE a.account_id = (     SELECT l.account_id      FROM loan l      ORDER BY l.amount DESC      LIMIT 1 )  ORDER BY t.date  LIMIT 1;
SELECT COUNT(*)  FROM client c  JOIN district d ON c.district_id = d.district_id  WHERE d.A2 = 'Jesenik' AND c.gender = 'F';
SELECT d.disp_id FROM disp d JOIN trans t ON d.account_id = t.account_id WHERE t.amount = 5100 AND t.date = '1998-09-02';
SELECT COUNT(*)  FROM account a  JOIN district d ON a.district_id = d.district_id  WHERE d.A2 = 'Litomerice' AND strftime('%Y', a.date) = '1996';
SELECT d.A2 FROM client c JOIN account a ON c.district_id = a.district_id JOIN district d ON c.district_id = d.district_id WHERE c.gender = 'F' AND c.birth_date = '1976-01-29';
SELECT c.birth_date FROM client c JOIN disp d ON c.client_id = d.client_id JOIN account a ON d.account_id = a.account_id JOIN loan l ON a.account_id = l.account_id WHERE l.amount = 98832 AND l.date = '1996-01-03';
SELECT a.account_id FROM account a JOIN client c ON a.account_id = c.client_id JOIN district d ON c.district_id = d.district_id WHERE d.A3 = 'Prague' ORDER BY a.date LIMIT 1;
SELECT CAST(COUNT(CASE WHEN c.gender = 'M' THEN 1 END) AS REAL) * 100 / COUNT(*)  FROM client c  JOIN district d ON c.district_id = d.district_id  WHERE d.A3 = 'south bohemia'  AND d.A4 = (SELECT MAX(A4) FROM district WHERE A3 = 'south bohemia');
SELECT    ((t1.balance - t2.balance) * 100.0 / t2.balance) AS increase_rate FROM    trans t1   JOIN trans t2 ON t1.account_id = t2.account_id   JOIN loan l ON t1.account_id = l.account_id   JOIN disp d ON l.account_id = d.account_id WHERE    l.date = '1993-07-05'   AND t1.date = '1998-12-27'   AND t2.date = '1993-03-22';
SELECT (SUM(CASE WHEN status = 'A' THEN amount ELSE 0 END) * 100.0 / SUM(amount)) AS percentage FROM loan;
SELECT (COUNT(CASE WHEN status = 'C' THEN 1 END) * 100.0 / COUNT(*)) AS percentage FROM loan WHERE amount < 100000;
SELECT      a.account_id,      d.A2 AS district_name,      d.A3 AS district_region FROM      account a JOIN      district d ON a.district_id = d.district_id WHERE      strftime('%Y', a.date) = '1993'      AND a.frequency = 'POPLATEK PO OBRATU';
SELECT a.account_id, a.frequency FROM account a JOIN district d ON a.district_id = d.district_id WHERE d.A2 = 'east Bohemia'   AND strftime('%Y', a.date) BETWEEN '1995' AND '2000';
SELECT a.account_id, a.date FROM account a JOIN district d ON a.district_id = d.district_id WHERE d.A2 = 'Prachatice';
SELECT d.A2 AS district, d.A3 AS region FROM loan l JOIN account a ON l.account_id = a.account_id JOIN district d ON a.district_id = d.district_id WHERE l.loan_id = 4990;
SELECT      l.account_id,     d.A2 AS district,     d.A3 AS region FROM      loan l JOIN      account a ON l.account_id = a.account_id JOIN      district d ON a.district_id = d.district_id WHERE      l.amount > 300000;
SELECT      l.loan_id,     d.A3 AS district,     d.A11 AS average_salary FROM      loan l JOIN      account a ON l.account_id = a.account_id JOIN      district d ON a.district_id = d.district_id WHERE      l.duration = 60;
SELECT      d.A2 AS district,     ((d.A13 - d.A12) / d.A12) * 100 AS unemployment_increment_percentage FROM      loan l JOIN      account a ON l.account_id = a.account_id JOIN      district d ON a.district_id = d.district_id WHERE      l.status = 'D'     AND d.A12 IS NOT NULL      AND d.A12 != 0      AND d.A13 IS NOT NULL;
SELECT      CAST(COUNT(CASE WHEN d.A2 = 'Decin' THEN 1 END) AS REAL) * 100 / COUNT(*) AS percentage FROM      account a JOIN      district d ON a.district_id = d.district_id WHERE      strftime('%Y', a.date) = '1993';
SELECT `account_id` FROM `account` WHERE `frequency` = 'POPLATEK MESICNE';
SELECT d.A2, COUNT(*) AS female_count FROM district d JOIN client c ON d.district_id = c.district_id WHERE c.gender = 'F' GROUP BY d.A2 ORDER BY female_count DESC LIMIT 9;
SELECT      d.A2,     t.amount FROM      trans t JOIN      account a ON t.account_id = a.account_id JOIN      district d ON a.district_id = d.district_id WHERE      t.type = 'VYDAJ'      AND t.date LIKE '1996-01%' ORDER BY      t.amount DESC LIMIT 10;
SELECT COUNT(*)  FROM account a JOIN district d ON a.district_id = d.district_id WHERE d.A3 = 'South Bohemia'    AND a.account_id NOT IN (     SELECT DISTINCT d2.account_id      FROM card c     JOIN disp d2 ON c.disp_id = d2.disp_id   );
SELECT d.A3 FROM district d JOIN account a ON d.district_id = a.district_id JOIN loan l ON a.account_id = l.account_id WHERE l.status IN ('C', 'D') GROUP BY d.A3 ORDER BY COUNT(*) DESC LIMIT 1;
SELECT AVG(l.amount) FROM loan l JOIN account a ON l.account_id = a.account_id JOIN disp d ON a.account_id = d.account_id JOIN client c ON d.client_id = c.client_id WHERE c.gender = 'M';
SELECT A2 AS district_name, A4 AS branch_location FROM district ORDER BY A13 DESC LIMIT 1;
SELECT COUNT(*)  FROM account  WHERE district_id = (     SELECT district_id      FROM district      ORDER BY A16 DESC      LIMIT 1 );
SELECT COUNT(*)  FROM `trans` t  JOIN `account` a ON t.account_id = a.account_id  WHERE t.operation = 'VYBER KARTOU'    AND a.frequency = 'POPLATEK MESICNE'    AND t.balance < 0;
SELECT COUNT(*)  FROM loan l  JOIN account a ON l.account_id = a.account_id  WHERE l.date BETWEEN '1995-01-01' AND '1997-12-31'    AND l.amount >= 250000    AND l.status = 'A'    AND a.frequency = 'POPLATEK MESICNE';
SELECT COUNT(*)  FROM loan  WHERE account_id IN (     SELECT account_id      FROM account      WHERE district_id = 1 )  AND status IN ('C', 'D');
SELECT COUNT(*)  FROM client c  JOIN district d ON c.district_id = d.district_id  WHERE c.gender = 'M'  AND d.district_id = (     SELECT district_id      FROM district      ORDER BY A15 DESC      LIMIT 1 OFFSET 1 )
SELECT COUNT(*)  FROM card c  JOIN disp d ON c.disp_id = d.disp_id  WHERE c.type = 'gold' AND d.type = 'OWNER';
SELECT COUNT(*)  FROM account a  JOIN district d ON a.district_id = d.district_id  WHERE d.A2 = 'Pisek';
SELECT DISTINCT d.district_id FROM district d JOIN client c ON d.district_id = c.district_id JOIN disp di ON c.client_id = di.client_id JOIN account a ON di.account_id = a.account_id JOIN trans t ON a.account_id = t.account_id WHERE t.date LIKE '1997%' AND t.amount > 10000;
SELECT DISTINCT a.account_id FROM account a JOIN `order` o ON a.account_id = o.account_id JOIN district d ON a.district_id = d.district_id WHERE o.k_symbol = 'SIPO' AND d.A2 = 'Pisek';
SELECT a.account_id FROM account a JOIN disp d ON a.account_id = d.account_id JOIN card c ON d.disp_id = c.disp_id WHERE c.type = 'gold';
SELECT AVG(t.amount)  FROM trans t  JOIN account a ON t.account_id = a.account_id  WHERE t.operation = 'VYBER KARTOU'    AND strftime('%Y', t.date) = '2021';
SELECT DISTINCT d.client_id FROM disp d JOIN trans t ON d.account_id = t.account_id WHERE t.operation = 'VYBER KARTOU'    AND t.date LIKE '1998%'    AND t.amount < (SELECT AVG(amount) FROM trans WHERE operation = 'VYBER KARTOU' AND date LIKE '1998%');
SELECT DISTINCT c.client_id FROM client c JOIN disp d ON c.client_id = d.client_id JOIN card ca ON d.disp_id = ca.disp_id JOIN loan l ON d.account_id = l.account_id WHERE c.gender = 'F' AND d.type = 'OWNER';
SELECT COUNT(*)  FROM client c  JOIN district d ON c.district_id = d.district_id  WHERE c.gender = 'F' AND d.A3 = 'south Bohemia';
SELECT a.account_id FROM account a JOIN district d ON a.district_id = d.district_id JOIN disp dp ON a.account_id = dp.account_id WHERE d.A2 = 'Tabor' AND dp.type = 'OWNER';
SELECT DISTINCT a.frequency FROM account a JOIN district d ON a.district_id = d.district_id WHERE a.frequency != 'OWNER' AND d.A11 > 8000 AND d.A11 <= 9000;
SELECT COUNT(*)  FROM account a JOIN district d ON a.district_id = d.district_id JOIN trans t ON a.account_id = t.account_id WHERE d.A3 = 'North Bohemia' AND t.bank = 'AB';
SELECT DISTINCT d.A2 FROM district d JOIN account a ON d.district_id = a.district_id JOIN trans t ON a.account_id = t.account_id WHERE t.type = 'VYDAJ';
SELECT AVG(d.A15)  FROM district d  JOIN account a ON d.district_id = a.district_id  WHERE d.A15 > 4000 AND strftime('%Y', a.date) >= '1997';
SELECT COUNT(*)  FROM card c JOIN disp d ON c.disp_id = d.disp_id WHERE c.type = 'classic' AND d.type = 'OWNER';
SELECT COUNT(*)  FROM client c  JOIN district d ON c.district_id = d.district_id  WHERE c.gender = 'M' AND d.A2 = 'Hl.m. Praha';
SELECT (COUNT(CASE WHEN type = 'gold' AND issued < '1998-01-01' THEN 1 END) * 100.0 / COUNT(*)) AS percentage FROM card;
SELECT c.gender, c.birth_date, c.district_id FROM client c JOIN disp d ON c.client_id = d.client_id JOIN loan l ON d.account_id = l.account_id WHERE l.amount = (SELECT MAX(amount) FROM loan) AND d.type = 'OWNER';
SELECT d.A15 FROM account a JOIN district d ON a.district_id = d.district_id WHERE a.account_id = 532;
SELECT account_id FROM `order` WHERE order_id = 33333;
SELECT t.* FROM trans t JOIN disp d ON t.account_id = d.account_id WHERE d.client_id = 3356 AND t.operation = 'VYBER';
SELECT COUNT(*)  FROM account a  JOIN loan l ON a.account_id = l.account_id  WHERE a.frequency = 'POPLATEK TYDNE' AND l.amount < 200000;
SELECT c.type FROM card c JOIN disp d ON c.disp_id = d.disp_id WHERE d.client_id = 13539;
SELECT d.A3 FROM client c JOIN district d ON c.district_id = d.district_id WHERE c.client_id = 3541;
SELECT d.A2 FROM district d JOIN account a ON d.district_id = a.district_id JOIN loan l ON a.account_id = l.account_id WHERE l.status = 'A' GROUP BY d.district_id ORDER BY COUNT(*) DESC LIMIT 1;
SELECT c.client_id, c.gender, c.birth_date FROM `order` o JOIN disp d ON o.account_id = d.account_id JOIN client c ON d.client_id = c.client_id WHERE o.order_id = 32423;
SELECT t.*  FROM trans t  JOIN account a ON t.account_id = a.account_id  WHERE a.district_id = 5;
SELECT COUNT(*)  FROM account a  JOIN district d ON a.district_id = d.district_id  WHERE d.A2 = 'Jesenik';
SELECT c.client_id FROM client c JOIN disp d ON c.client_id = d.client_id JOIN card ca ON d.disp_id = ca.disp_id WHERE ca.type = 'junior' AND ca.issued >= '1997-01-01';
SELECT      CAST(SUM(CASE WHEN c.gender = 'F' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*)  FROM      client c  JOIN      district d ON c.district_id = d.district_id  WHERE      d.A11 > 10000;
SELECT    ((SUM(CASE WHEN strftime('%Y', l.date) = '1997' THEN l.amount ELSE 0 END) -      SUM(CASE WHEN strftime('%Y', l.date) = '1996' THEN l.amount ELSE 0 END)) * 100.0 /     NULLIF(SUM(CASE WHEN strftime('%Y', l.date) = '1996' THEN l.amount ELSE 0 END), 0)) AS growth_rate FROM loan l JOIN account a ON l.account_id = a.account_id JOIN disp d ON a.account_id = d.account_id JOIN client c ON d.client_id = c.client_id WHERE c.gender = 'M' AND strftime('%Y', l.date) IN ('1996', '1997');
SELECT COUNT(*)  FROM `trans`  WHERE `operation` = 'VYBER KARTOU' AND strftime('%Y', `date`) > '1995';
SELECT      (SELECT A16 FROM district WHERE A3 = 'North Bohemia') -      (SELECT A16 FROM district WHERE A3 = 'East Bohemia') AS crime_difference;
SELECT COUNT(*)  FROM `disp`  WHERE `account_id` BETWEEN 1 AND 10    AND `type` IN ('OWNER', 'DISPONENT');
SELECT    COUNT(*) AS statement_requests,   (SELECT k_symbol FROM `trans` WHERE `account_id` = 3 AND `amount` = -3539 LIMIT 1) AS debit_purpose FROM `trans` WHERE `account_id` = 3 AND `k_symbol` = 'VYBER';
SELECT strftime('%Y', c.birth_date)  FROM client c  JOIN disp d ON c.client_id = d.client_id  WHERE d.type = 'OWNER' AND d.disp_id = 130;
SELECT COUNT(*)  FROM account a  JOIN disp d ON a.account_id = d.account_id  WHERE d.type = 'OWNER' AND a.frequency = 'POPLATEK PO OBRATU';
SELECT l.amount, l.status FROM loan l JOIN account a ON l.account_id = a.account_id JOIN disp d ON a.account_id = d.account_id WHERE d.client_id = 992;
SELECT t.balance, c.gender FROM trans t JOIN account a ON t.account_id = a.account_id JOIN disp d ON a.account_id = d.account_id JOIN client c ON d.client_id = c.client_id WHERE t.trans_id = 851 AND c.client_id = 4;
SELECT c.type FROM card c JOIN disp d ON c.disp_id = d.disp_id WHERE d.client_id = 9;
