SELECT      CAST(COUNT(CASE WHEN c.gender = 'F' THEN 1 END) AS REAL) * 100 / COUNT(*) AS percentage_female FROM      client c JOIN      disp d ON c.client_id = d.client_id JOIN      account a ON d.account_id = a.account_id JOIN      district dt ON a.district_id = dt.district_id WHERE      dt.A3 = 'Prague';
SELECT CAST(COUNT(CASE WHEN c.gender = 'M' THEN 1 END) AS REAL) * 100 / COUNT(*)  FROM client c  JOIN disp d ON c.client_id = d.client_id  JOIN account a ON d.account_id = a.account_id  WHERE a.frequency = 'POPLATEK TYDNE';
SELECT COUNT(*)  FROM client c JOIN disp d ON c.client_id = d.client_id JOIN account a ON d.account_id = a.account_id WHERE a.frequency = 'POPLATEK TYDNE' AND d.type = 'OWNER';
SELECT a.account_id FROM account a JOIN loan l ON a.account_id = l.account_id WHERE l.duration > 24   AND l.status = 'A'   AND a.date < '1997-01-01' ORDER BY l.amount ASC LIMIT 1;
SELECT a.account_id FROM account a JOIN disp d ON a.account_id = d.account_id JOIN client c ON d.client_id = c.client_id JOIN district dt ON c.district_id = dt.district_id WHERE c.gender = 'F'   AND c.birth_date = (     SELECT MIN(birth_date)     FROM client     WHERE gender = 'F'   )   AND dt.A11 = (     SELECT MIN(A11)     FROM district     WHERE district_id IN (       SELECT c2.district_id       FROM client c2       JOIN disp d2 ON c2.client_id = d2.client_id       JOIN account a2 ON d2.account_id = a2.account_id       WHERE c2.gender = 'F'         AND c2.birth_date = (           SELECT MIN(birth_date)           FROM client           WHERE gender = 'F'         )     )   );
SELECT COUNT(*)  FROM client c  JOIN district d ON c.district_id = d.district_id  WHERE c.birth_date LIKE '1920%' AND d.A3 = 'east Bohemia';
SELECT COUNT(*)  FROM loan l  JOIN account a ON l.account_id = a.account_id  WHERE l.duration = 24 AND a.frequency = 'POPLATEK TYDNE';
SELECT AVG(l.amount)  FROM loan l  JOIN account a ON l.account_id = a.account_id  WHERE l.status IN ('C', 'D')  AND a.frequency = 'POPLATEK PO OBRATU';
SELECT c.client_id, c.district_id FROM client c JOIN disp d ON c.client_id = d.client_id WHERE d.type = 'OWNER';
SELECT c.client_id, CAST((strftime('%Y', 'now') - strftime('%Y', c.birth_date)) AS INTEGER) AS age FROM client c JOIN disp d ON c.client_id = d.client_id JOIN card ca ON d.disp_id = ca.disp_id WHERE ca.type = 'gold' AND d.type = 'OWNER';
SELECT bond_type FROM bond GROUP BY bond_type ORDER BY COUNT(*) DESC LIMIT 1;
SELECT COUNT(*)  FROM atom a  JOIN molecule m ON a.molecule_id = m.molecule_id  WHERE m.label = '-' AND a.element = 'cl';
SELECT AVG(CASE WHEN a.element = 'o' THEN 1 ELSE 0 END) FROM molecule m JOIN bond b ON m.molecule_id = b.molecule_id JOIN atom a ON m.molecule_id = a.molecule_id WHERE b.bond_type = '-';
SELECT CAST(SUM(CASE WHEN b.bond_type = '-' THEN 1 ELSE 0 END) AS REAL) / COUNT(*)  FROM molecule m  JOIN bond b ON m.molecule_id = b.molecule_id  WHERE m.label = '+';
SELECT COUNT(*)  FROM atom a  JOIN molecule m ON a.molecule_id = m.molecule_id  WHERE a.element = 'na' AND m.label = '-'
SELECT DISTINCT m.molecule_id FROM molecule m JOIN bond b ON m.molecule_id = b.molecule_id WHERE b.bond_type = '#' AND m.label = '+';
SELECT CAST(SUM(CASE WHEN a.element = 'c' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*)  FROM atom a  JOIN bond b ON a.molecule_id = b.molecule_id  WHERE b.bond_type = '=';
SELECT COUNT(*) FROM bond WHERE bond_type = '#';
SELECT COUNT(*) FROM atom WHERE element != 'br';
SELECT COUNT(*)  FROM molecule  WHERE molecule_id BETWEEN 'TR000' AND 'TR099'  AND label = '+';
