SELECT DISTINCT m.molecule_id FROM molecule m JOIN bond b ON m.molecule_id = b.molecule_id WHERE b.bond_type = '=' ORDER BY m.molecule_id LIMIT 5;
SELECT ROUND(CAST(SUM(CASE WHEN bond_type = '=' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(bond_id), 5) AS percent FROM bond WHERE molecule_id = 'TR008';
SELECT ROUND(COUNT(CASE WHEN label = '+' THEN 1 END) * 100.0 / COUNT(*), 3) AS percentage FROM molecule;
SELECT ROUND(CAST(SUM(CASE WHEN element = 'h' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*), 4) AS percent FROM atom WHERE molecule_id = 'TR206';
SELECT DISTINCT `bond_type` FROM `bond` WHERE `molecule_id` = 'TR000';
