SELECT a1.element, a2.element FROM atom a1 JOIN connected c ON a1.atom_id = c.atom_id JOIN bond b ON c.bond_id = b.bond_id JOIN atom a2 ON c.atom_id2 = a2.atom_id WHERE b.bond_type = '#';
SELECT COUNT(*) * 100.0 / (SELECT COUNT(*) FROM bond)  FROM (     SELECT a1.element AS element1, a2.element AS element2, COUNT(*) AS cnt     FROM connected c     JOIN atom a1 ON c.atom_id = a1.atom_id     JOIN atom a2 ON c.atom_id2 = a2.atom_id     GROUP BY a1.element, a2.element     ORDER BY cnt DESC     LIMIT 1 ) AS most_common;
