SELECT DISTINCT r.year FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE c.name = 'Silverstone';
SELECT r.url FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE c.name = 'Silverstone';
SELECT r.time FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE r.name LIKE '%Abu Dhabi%' AND r.year BETWEEN 2010 AND 2019;
SELECT COUNT(*)  FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE c.country = 'Italy';
SELECT r.date FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE c.name = 'Circuit de Barcelona-Catalunya';
SELECT c.url FROM circuits c JOIN races r ON c.circuitId = r.circuitId WHERE r.name = 'Spanish Grand Prix' AND r.year = 2009;
SELECT MIN(r.fastestLapTime)  FROM results r  JOIN drivers d ON r.driverId = d.driverId  WHERE d.forename = 'Lewis' AND d.surname = 'Hamilton';
SELECT d.forename, d.surname FROM results r JOIN drivers d ON r.driverId = d.driverId WHERE r.fastestLapSpeed IS NOT NULL ORDER BY CAST(r.fastestLapSpeed AS REAL) DESC LIMIT 1;
SELECT d.driverRef FROM drivers d JOIN results r ON d.driverId = r.driverId JOIN races ra ON r.raceId = ra.raceId WHERE ra.name = 'Canadian Grand Prix' AND ra.year = 2007 AND r.position = 1;
SELECT r.name FROM races r JOIN results res ON r.raceId = res.raceId JOIN drivers d ON res.driverId = d.driverId WHERE d.forename = 'Lewis' AND d.surname = 'Hamilton';
SELECT r.name FROM races r JOIN results res ON r.raceId = res.raceId JOIN drivers d ON res.driverId = d.driverId WHERE d.forename = 'Lewis' AND d.surname = 'Hamilton' ORDER BY res.rank ASC LIMIT 1;
SELECT MAX(CAST(res.fastestLapSpeed AS REAL)) FROM races r JOIN results res ON r.raceId = res.raceId WHERE r.name = 'Spanish Grand Prix' AND r.year = 2009;
SELECT DISTINCT r.year FROM races r JOIN results res ON r.raceId = res.raceId JOIN drivers d ON res.driverId = d.driverId WHERE d.forename = 'Lewis' AND d.surname = 'Hamilton';
SELECT r.positionOrder FROM results r JOIN drivers d ON r.driverId = d.driverId JOIN races ra ON r.raceId = ra.raceId WHERE d.forename = 'Lewis' AND d.surname = 'Hamilton'   AND ra.name = 'Chinese Grand Prix'   AND ra.year = 2008;
SELECT d.forename, d.surname FROM results r JOIN drivers d ON r.driverId = d.driverId JOIN races ra ON r.raceId = ra.raceId WHERE ra.year = 1989 AND ra.name = 'Australian Grand Prix' AND r.grid = 4;
SELECT COUNT(*)  FROM results r  JOIN races ra ON r.raceId = ra.raceId  WHERE ra.name = 'Australian Grand Prix' AND ra.year = 2008 AND r.time IS NOT NULL;
SELECT MIN(lapTimes.milliseconds)  FROM lapTimes  JOIN races ON lapTimes.raceId = races.raceId  JOIN drivers ON lapTimes.driverId = drivers.driverId  WHERE races.name = 'Australian Grand Prix'  AND races.year = 2008  AND drivers.forename = 'Lewis'  AND drivers.surname = 'Hamilton';
SELECT r.time FROM results r JOIN races ra ON r.raceId = ra.raceId WHERE ra.year = 2008 AND ra.name = 'Chinese Grand Prix' AND r.position = 2;
SELECT d.forename, d.surname, d.url FROM results r JOIN races ra ON r.raceId = ra.raceId JOIN drivers d ON r.driverId = d.driverId WHERE ra.name = 'Australian Grand Prix' AND ra.year = 2008 AND r.positionText = '1' AND r.time IS NOT NULL;
SELECT COUNT(*)  FROM drivers d  JOIN results r ON d.driverId = r.driverId  JOIN races ra ON r.raceId = ra.raceId  WHERE d.nationality = 'British'  AND ra.name = 'Australian Grand Prix'  AND ra.year = 2008;
SELECT COUNT(*)  FROM results r JOIN races ra ON r.raceId = ra.raceId JOIN drivers d ON r.driverId = d.driverId WHERE ra.name = 'Chinese Grand Prix'    AND ra.year = 2008    AND r.time IS NOT NULL    AND EXISTS (     SELECT 1      FROM results r2      WHERE r2.driverId = d.driverId   );
SELECT SUM(r.points)  FROM results r  JOIN drivers d ON r.driverId = d.driverId  WHERE d.forename = 'Lewis' AND d.surname = 'Hamilton';
SELECT AVG(     CAST(SUBSTR(r.fastestLapTime, 1, INSTR(r.fastestLapTime, ':') - 1) AS INTEGER) * 60 +     CAST(SUBSTR(r.fastestLapTime, INSTR(r.fastestLapTime, ':') + 1, INSTR(r.fastestLapTime, '.') - INSTR(r.fastestLapTime, ':') - 1) AS INTEGER) +     CAST(SUBSTR(r.fastestLapTime, INSTR(r.fastestLapTime, '.') + 1) AS REAL) / 1000 ) AS avg_fastest_lap_time_seconds FROM results r JOIN drivers d ON r.driverId = d.driverId WHERE d.forename = 'Lewis' AND d.surname = 'Hamilton' AND r.fastestLapTime IS NOT NULL;
SELECT CAST(COUNT(CASE WHEN r.time IS NOT NULL THEN 1 END) AS REAL) * 100 / COUNT(*)  FROM races ra  JOIN results r ON ra.raceId = r.raceId  WHERE ra.year = 2008 AND ra.name = 'Australian Grand Prix';
SELECT      ((t2.milliseconds - t1.milliseconds) * 100.0 / t2.milliseconds) AS percentage_faster FROM      results t1 JOIN      races r ON t1.raceId = r.raceId JOIN      results t2 ON t2.raceId = r.raceId WHERE      r.name = 'Australian Grand Prix' AND r.year = 2008      AND t1.position = 1      AND t1.statusId = 1      AND t2.position = (         SELECT MAX(t3.position)          FROM results t3          WHERE t3.raceId = r.raceId            AND t3.statusId = 1     )     AND t1.milliseconds IS NOT NULL      AND t2.milliseconds IS NOT NULL;
SELECT COUNT(*)  FROM circuits  WHERE location = 'Adelaide' AND country = 'Australia';
SELECT lat, lng FROM circuits WHERE country = 'USA';
SELECT COUNT(*)  FROM drivers  WHERE nationality = 'British' AND strftime('%Y', dob) > '1980';
SELECT MAX(cr.points)  FROM constructorResults cr JOIN constructors c ON cr.constructorId = c.constructorId WHERE c.nationality = 'British';
SELECT c.name FROM constructors c JOIN constructorStandings cs ON c.constructorId = cs.constructorId ORDER BY cs.points DESC LIMIT 1;
SELECT c.name FROM constructors c JOIN constructorResults cr ON c.constructorId = cr.constructorId WHERE cr.raceId = 291 AND cr.points = 0;
SELECT COUNT(*)  FROM constructors c JOIN constructorResults cr ON c.constructorId = cr.constructorId WHERE c.nationality = 'Japanese' AND cr.points = 0 GROUP BY c.constructorId HAVING COUNT(cr.raceId) = 2;
SELECT DISTINCT c.name FROM constructors c JOIN constructorStandings cs ON c.constructorId = cs.constructorId WHERE cs.position = 1;
SELECT COUNT(*)  FROM constructors c JOIN results r ON c.constructorId = r.constructorId WHERE c.nationality = 'French' AND r.laps > 50;
SELECT      CAST(COUNT(CASE WHEN r.time IS NOT NULL THEN 1 END) AS REAL) * 100 / COUNT(*) AS race_completion_percentage FROM      results r JOIN      drivers d ON r.driverId = d.driverId JOIN      races ra ON r.raceId = ra.raceId WHERE      d.nationality = 'Japanese'      AND ra.year BETWEEN 2007 AND 2009;
SELECT r.year, AVG(res.milliseconds / 1000.0) AS average_time_seconds FROM races r JOIN results res ON r.raceId = res.raceId JOIN status s ON res.statusId = s.statusId WHERE r.year < 1975 AND s.status = 'Finished' AND res.position = 1 AND res.time IS NOT NULL GROUP BY r.year;
SELECT d.forename, d.surname FROM drivers d JOIN driverStandings ds ON d.driverId = ds.driverId WHERE strftime('%Y', d.dob) > '1975' AND ds.position = 2;
SELECT COUNT(*)  FROM drivers d  JOIN results r ON d.driverId = r.driverId  WHERE d.nationality = 'Italian' AND r.time IS NULL;
SELECT d.forename, d.surname FROM results r JOIN drivers d ON r.driverId = d.driverId WHERE r.fastestLapTime IS NOT NULL ORDER BY r.fastestLapTime LIMIT 1;
SELECT r.fastestLap FROM results r JOIN races ra ON r.raceId = ra.raceId WHERE ra.year = 2009 AND r.position = 1;
SELECT AVG(CAST(res.fastestLapSpeed AS REAL)) FROM races r JOIN results res ON r.raceId = res.raceId WHERE r.name = 'Spanish Grand Prix' AND r.year = 2009;
SELECT r.name, r.year FROM races r JOIN results res ON r.raceId = res.raceId WHERE res.milliseconds IS NOT NULL ORDER BY res.milliseconds ASC LIMIT 1;
SELECT      CAST(COUNT(CASE WHEN strftime('%Y', d.dob) < '1985' AND r.laps > 50 THEN 1 END) AS REAL) * 100 / COUNT(*)  FROM      drivers d  JOIN      results r ON d.driverId = r.driverId  JOIN      races ra ON r.raceId = ra.raceId  WHERE      ra.year BETWEEN 2000 AND 2005;
SELECT COUNT(*)  FROM drivers d  JOIN lapTimes l ON d.driverId = l.driverId  WHERE d.nationality = 'French'  AND CAST(SUBSTR(l.time, 1, INSTR(l.time, ':') - 1) AS INTEGER) * 60 +      CAST(SUBSTR(l.time, INSTR(l.time, ':') + 1) AS REAL) < 120;
SELECT code FROM drivers WHERE nationality = 'American';
SELECT raceId FROM races WHERE year = 2009;
SELECT COUNT(*)  FROM results  WHERE raceId = 18;
SELECT COUNT(*)  FROM (     SELECT driverId, nationality      FROM drivers      WHERE nationality = 'Dutch'      ORDER BY dob DESC      LIMIT 3 ) AS top_3_youngest;
SELECT driverRef FROM drivers WHERE forename = 'Robert' AND surname = 'Kubica';
SELECT COUNT(*)  FROM drivers  WHERE nationality = 'British' AND strftime('%Y', dob) = '1980';
SELECT d.forename, d.surname, MIN(lt.time) AS earliest_lap_time FROM drivers d JOIN lapTimes lt ON d.driverId = lt.driverId WHERE d.nationality = 'German'    AND strftime('%Y', d.dob) BETWEEN '1980' AND '1990' GROUP BY d.driverId, d.forename, d.surname ORDER BY earliest_lap_time ASC LIMIT 3;
SELECT driverRef FROM drivers WHERE nationality = 'German' ORDER BY dob ASC LIMIT 1;
SELECT d.driverId, d.code FROM drivers d JOIN results r ON d.driverId = r.driverId WHERE strftime('%Y', d.dob) = '1971' AND r.fastestLapTime IS NOT NULL;
SELECT d.forename, d.surname, MAX(lt.time) AS latest_lap_time FROM drivers d JOIN lapTimes lt ON d.driverId = lt.driverId WHERE d.nationality = 'Spanish' AND strftime('%Y', d.dob) < '1982' GROUP BY d.driverId, d.forename, d.surname ORDER BY latest_lap_time DESC LIMIT 10;
SELECT r.year FROM races r JOIN results res ON r.raceId = res.raceId WHERE res.fastestLapTime IS NOT NULL ORDER BY res.fastestLapTime ASC LIMIT 1;
SELECT year FROM races r JOIN results res ON r.raceId = res.raceId WHERE res.fastestLapSpeed IS NOT NULL ORDER BY CAST(res.fastestLapSpeed AS REAL) ASC LIMIT 1;
SELECT driverId FROM lapTimes WHERE lap = 1 ORDER BY time ASC LIMIT 5;
SELECT COUNT(*)  FROM results  WHERE raceId > 50 AND raceId < 100    AND statusId = 2    AND time IS NOT NULL;
SELECT COUNT(*) AS count, location, lat, lng FROM circuits WHERE country = 'Austria';
SELECT `raceId` FROM `results` WHERE `time` IS NOT NULL GROUP BY `raceId` ORDER BY COUNT(*) DESC LIMIT 1;
SELECT d.driverRef, d.nationality, d.dob FROM qualifying q JOIN drivers d ON q.driverId = d.driverId WHERE q.raceId = 23 AND q.q2 IS NOT NULL;
SELECT      r.year,     d.forename,     d.surname,     r.name,     r.date,     r.time FROM      drivers d JOIN      qualifying q ON d.driverId = q.driverId JOIN      races r ON q.raceId = r.raceId WHERE      d.dob = (SELECT MAX(dob) FROM drivers)     AND r.date = (         SELECT MIN(r2.date)         FROM drivers d2         JOIN qualifying q2 ON d2.driverId = q2.driverId         JOIN races r2 ON q2.raceId = r2.raceId         WHERE d2.dob = (SELECT MAX(dob) FROM drivers)     );
SELECT COUNT(*)  FROM drivers d  JOIN results r ON d.driverId = r.driverId  JOIN status s ON r.statusId = s.statusId  WHERE d.nationality = 'American' AND s.status = 'Puncture';
SELECT url  FROM constructors  WHERE nationality = 'Italian'  ORDER BY constructorId DESC  LIMIT 1;
SELECT c.url FROM constructors c JOIN constructorStandings cs ON c.constructorId = cs.constructorId GROUP BY c.constructorId, c.url ORDER BY SUM(cs.wins) DESC LIMIT 1;
SELECT d.forename, d.surname FROM drivers d JOIN lapTimes lt ON d.driverId = lt.driverId JOIN races r ON lt.raceId = r.raceId WHERE r.name = 'French Grand Prix' AND lt.lap = 3 ORDER BY lt.time DESC LIMIT 1;
SELECT raceId, MIN(milliseconds) AS min_milliseconds FROM lapTimes WHERE lap = 1 GROUP BY raceId ORDER BY min_milliseconds LIMIT 1;
SELECT AVG(r.fastestLapTime) FROM results r JOIN races ra ON r.raceId = ra.raceId WHERE ra.year = 2006 AND ra.name = 'United States Grand Prix' AND r.rank < 11;
SELECT d.forename, d.surname FROM drivers d JOIN pitStops p ON d.driverId = p.driverId WHERE d.nationality = 'German' AND strftime('%Y', d.dob) BETWEEN '1980' AND '1985' GROUP BY d.driverId, d.forename, d.surname ORDER BY AVG(CAST(p.duration AS REAL)) ASC LIMIT 3;
SELECT d.forename, d.surname, r.time FROM races r JOIN results res ON r.raceId = res.raceId JOIN drivers d ON res.driverId = d.driverId WHERE r.name = 'Canadian Grand Prix' AND r.year = 2008 AND res.position = 1;
SELECT c.constructorRef, c.url FROM constructors c JOIN results r ON c.constructorId = r.constructorId JOIN races ra ON r.raceId = ra.raceId WHERE ra.name = 'Singapore Grand Prix' AND ra.year = 2009 AND r.position = 1;
SELECT forename, surname, dob FROM drivers WHERE nationality = 'Austrian' AND strftime('%Y', dob) BETWEEN '1981' AND '1991';
SELECT forename || ' ' || surname AS full_name, url, dob FROM drivers WHERE nationality = 'German' AND strftime('%Y', dob) BETWEEN '1971' AND '1985' ORDER BY dob DESC;
SELECT location, country, lat, lng FROM circuits WHERE name = 'Hungaroring';
SELECT      SUM(cr.points) AS total_points,     c.name AS constructor_name,     c.nationality AS constructor_nationality FROM      constructorResults cr JOIN      races r ON cr.raceId = r.raceId JOIN      constructors c ON cr.constructorId = c.constructorId WHERE      r.name = 'Monaco Grand Prix'      AND r.year BETWEEN 1980 AND 2010 GROUP BY      c.constructorId, c.name, c.nationality ORDER BY      total_points DESC LIMIT 1;
SELECT AVG(r.points)  FROM results r JOIN drivers d ON r.driverId = d.driverId JOIN races ra ON r.raceId = ra.raceId WHERE d.forename = 'Lewis' AND d.surname = 'Hamilton' AND ra.name = 'Turkish Grand Prix';
SELECT COUNT(*) * 1.0 / 10 AS annual_average_races FROM races WHERE date BETWEEN '2000-01-01' AND '2010-12-31';
SELECT nationality FROM drivers GROUP BY nationality ORDER BY COUNT(*) DESC LIMIT 1;
SELECT wins FROM driverStandings WHERE position = 91;
SELECT r.name FROM races r JOIN results res ON r.raceId = res.raceId WHERE res.fastestLapTime = (     SELECT MIN(fastestLapTime)     FROM results     WHERE fastestLapTime IS NOT NULL )
SELECT c.location || ', ' || c.country AS full_location FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE r.date = (SELECT MAX(date) FROM races);
SELECT d.forename, d.surname FROM qualifying q JOIN races r ON q.raceId = r.raceId JOIN circuits c ON r.circuitId = c.circuitId JOIN drivers d ON q.driverId = d.driverId WHERE r.year = 2008    AND c.name = 'Marina Bay Street Circuit'   AND q.position = 1 ORDER BY q.q3 LIMIT 1;
SELECT d.forename || ' ' || d.surname AS full_name, d.nationality, r.name AS race_name FROM drivers d JOIN results res ON d.driverId = res.driverId JOIN races r ON res.raceId = r.raceId WHERE d.dob = (SELECT MAX(dob) FROM drivers) ORDER BY r.date LIMIT 1;
SELECT COUNT(*)  FROM results r  JOIN races ra ON r.raceId = ra.raceId  WHERE ra.name = 'Canadian Grand Prix' AND r.statusId = 3;
SELECT COALESCE(SUM(ds.wins), 0) AS wins, d.forename, d.surname FROM drivers d CROSS JOIN (SELECT MIN(dob) AS min_dob FROM drivers) AS oldest LEFT JOIN driverStandings ds ON d.driverId = ds.driverId WHERE d.dob IS NOT DISTINCT FROM oldest.min_dob GROUP BY d.driverId, d.forename, d.surname LIMIT 1;
SELECT MAX(duration) FROM pitStops;
SELECT MIN(time) FROM lapTimes;
SELECT MAX(p.duration) FROM pitStops p JOIN drivers d ON p.driverId = d.driverId WHERE d.forename = 'Lewis' AND d.surname = 'Hamilton';
SELECT p.lap FROM pitStops p JOIN races r ON p.raceId = r.raceId JOIN drivers d ON p.driverId = d.driverId WHERE r.name = 'Australian Grand Prix' AND r.year = 2011 AND d.forename = 'Lewis' AND d.surname = 'Hamilton';
SELECT p.duration FROM pitStops p JOIN races r ON p.raceId = r.raceId WHERE r.name = 'Australian Grand Prix' AND r.year = 2011;
SELECT MIN(lt.time) AS lap_record FROM lapTimes lt JOIN drivers d ON lt.driverId = d.driverId WHERE d.forename = 'Lewis' AND d.surname = 'Hamilton';
SELECT d.forename, d.surname FROM drivers d JOIN lapTimes lt ON d.driverId = lt.driverId ORDER BY lt.time LIMIT 20;
SELECT r.position FROM results r JOIN drivers d ON r.driverId = d.driverId WHERE d.forename = 'Lewis' AND d.surname = 'Hamilton' AND r.time = (     SELECT MIN(time)     FROM results     WHERE driverId = d.driverId );
SELECT MIN(l.time) AS lap_record FROM lapTimes l JOIN races r ON l.raceId = r.raceId WHERE r.name = 'Austrian Grand Prix';
SELECT lt.time FROM lapTimes lt JOIN races r ON lt.raceId = r.raceId JOIN circuits c ON r.circuitId = c.circuitId WHERE c.country = 'Italy' ORDER BY lt.time ASC LIMIT 1;
SELECT r.name FROM races r JOIN circuits c ON r.circuitId = c.circuitId JOIN lapTimes l ON r.raceId = l.raceId WHERE c.country = 'Austria' ORDER BY l.milliseconds ASC LIMIT 1;
SELECT ps.duration FROM races r JOIN circuits c ON r.circuitId = c.circuitId JOIN lapTimes lt ON r.raceId = lt.raceId JOIN pitStops ps ON r.raceId = ps.raceId AND lt.driverId = ps.driverId WHERE c.name = 'Austrian Grand Prix Circuit'   AND lt.time = (     SELECT MIN(lt2.time)     FROM lapTimes lt2     JOIN races r2 ON lt2.raceId = r2.raceId     JOIN circuits c2 ON r2.circuitId = c2.circuitId     WHERE c2.name = 'Austrian Grand Prix Circuit'   ) LIMIT 1;
SELECT lat, lng FROM circuits JOIN races ON circuits.circuitId = races.circuitId JOIN lapTimes ON races.raceId = lapTimes.raceId WHERE lapTimes.time = '1:29.488';
SELECT AVG(p.milliseconds) FROM pitStops p JOIN drivers d ON p.driverId = d.driverId WHERE d.forename = 'Lewis' AND d.surname = 'Hamilton';
SELECT AVG(lt.milliseconds) FROM lapTimes lt JOIN races r ON lt.raceId = r.raceId JOIN circuits c ON r.circuitId = c.circuitId WHERE c.country = 'Italy';
SELECT player_api_id FROM Player_Attributes WHERE overall_rating = (SELECT MAX(overall_rating) FROM Player_Attributes)
SELECT height, player_name FROM Player WHERE height = (SELECT MAX(height) FROM Player);
SELECT preferred_foot FROM Player_Attributes WHERE potential = (SELECT MIN(potential) FROM Player_Attributes);
SELECT COUNT(*)  FROM Player_Attributes  WHERE overall_rating >= 60    AND overall_rating < 65    AND defensive_work_rate = 'low';
SELECT player_api_id FROM Player_Attributes ORDER BY crossing DESC LIMIT 5;
SELECT l.name FROM League l JOIN Match m ON l.id = m.league_id WHERE m.season = '2015/2016' GROUP BY l.name ORDER BY SUM(m.home_team_goal + m.away_team_goal) DESC LIMIT 1;
SELECT `home_team_api_id` FROM `Match` WHERE `season` = '2015/2016' AND `home_team_goal` < `away_team_goal` GROUP BY `home_team_api_id` ORDER BY COUNT(*) ASC LIMIT 1;
SELECT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id ORDER BY pa.penalties DESC LIMIT 10;
SELECT T1.team_long_name FROM Team AS T1 JOIN Match AS T2 ON T1.team_api_id = T2.away_team_api_id JOIN League AS T3 ON T2.league_id = T3.id WHERE T3.name = 'Scotland Premier League' AND T2.season = '2009/2010' AND T2.away_team_goal > T2.home_team_goal GROUP BY T1.team_long_name ORDER BY COUNT(*) DESC LIMIT 1;
SELECT buildUpPlaySpeed FROM Team_Attributes ORDER BY buildUpPlaySpeed DESC LIMIT 4;
SELECT l.name FROM League l JOIN Match m ON l.id = m.league_id WHERE m.season = '2015/2016' GROUP BY l.name ORDER BY SUM(CASE WHEN m.home_team_goal = m.away_team_goal THEN 1 ELSE 0 END) DESC LIMIT 1;
SELECT      CAST((strftime('%Y', 'now') - strftime('%Y', p.birthday)) AS INTEGER) -      CASE          WHEN strftime('%m-%d', 'now') < strftime('%m-%d', p.birthday) THEN 1          ELSE 0      END AS age FROM      Player p JOIN      Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE      pa.sprint_speed >= 97      AND strftime('%Y', pa.date) >= '2013'      AND strftime('%Y', pa.date) <= '2015';
SELECT l.name, COUNT(*) AS match_count FROM Match m JOIN League l ON m.league_id = l.id GROUP BY l.name ORDER BY match_count DESC LIMIT 1;
SELECT AVG(height)  FROM Player  WHERE birthday >= '1990-01-01 00:00:00' AND birthday < '1996-01-01 00:00:00';
SELECT player_api_id FROM Player_Attributes WHERE substr(date, 1, 4) = '2010'   AND overall_rating = (     SELECT MAX(overall_rating)     FROM Player_Attributes     WHERE substr(date, 1, 4) = '2010'   );
SELECT team_fifa_api_id FROM Team_Attributes WHERE buildUpPlaySpeed > 50 AND buildUpPlaySpeed < 60;
SELECT T1.team_long_name FROM Team AS T1 JOIN Team_Attributes AS T2 ON T1.team_api_id = T2.team_api_id WHERE strftime('%Y', T2.date) = '2012'   AND T2.buildUpPlayPassing > (     SELECT AVG(T2_inner.buildUpPlayPassing)     FROM Team_Attributes AS T2_inner     WHERE T2_inner.buildUpPlayPassing IS NOT NULL       AND strftime('%Y', T2_inner.date) = '2012'   );
SELECT CAST(SUM(CASE WHEN pa.preferred_foot = 'left' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*)  FROM Player p  JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id  WHERE strftime('%Y', p.birthday) BETWEEN '1987' AND '1992';
SELECT      l.name AS league_name,     SUM(m.home_team_goal + m.away_team_goal) AS total_goals FROM      League l JOIN      Match m ON l.id = m.league_id GROUP BY      l.name ORDER BY      total_goals ASC LIMIT 5;
SELECT AVG(long_shots)  FROM Player_Attributes pa  JOIN Player p ON pa.player_fifa_api_id = p.player_fifa_api_id  WHERE p.player_name = 'Ahmed Samir Farag';
SELECT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE p.height > 180 GROUP BY p.player_name ORDER BY AVG(pa.heading_accuracy) DESC LIMIT 10;
SELECT T1.team_long_name FROM Team AS T1 JOIN Team_Attributes AS T2 ON T1.team_api_id = T2.team_api_id WHERE T2.buildUpPlayDribblingClass = 'Normal'   AND T2.date >= '2014-01-01 00:00:00'   AND T2.date <= '2014-01-31 00:00:00'   AND T2.chanceCreationPassing < (     SELECT AVG(chanceCreationPassing)     FROM Team_Attributes     WHERE buildUpPlayDribblingClass = 'Normal'       AND date >= '2014-01-01 00:00:00'       AND date <= '2014-01-31 00:00:00'   ) ORDER BY T2.chanceCreationPassing DESC;
SELECT L.name FROM League L JOIN Match M ON L.id = M.league_id WHERE M.season = '2009/2010' GROUP BY L.name HAVING AVG(M.home_team_goal) > AVG(M.away_team_goal);
SELECT team_short_name FROM Team WHERE team_long_name = 'Queens Park Rangers';
SELECT player_name  FROM Player  WHERE substr(birthday, 1, 4) = '1970' AND substr(birthday, 6, 2) = '10';
SELECT pa.attacking_work_rate FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE p.player_name = 'Franco Zennaro';
SELECT ta.buildUpPlayPositioningClass FROM Team t JOIN Team_Attributes ta ON t.team_api_id = ta.team_api_id WHERE t.team_long_name = 'ADO Den Haag';
SELECT pa.heading_accuracy FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE p.player_name = 'Francois Affolter' AND pa.date = '2014-09-18 00:00:00';
SELECT pa.overall_rating FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Gabriel Tamas' AND strftime('%Y', pa.date) = '2011';
SELECT COUNT(*)  FROM Match m JOIN League l ON m.league_id = l.id WHERE l.name = 'Scotland Premier League' AND m.season = '2015/2016';
SELECT preferred_foot FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.birthday = (SELECT MAX(birthday) FROM Player) LIMIT 1;
SELECT player_name FROM Player JOIN Player_Attributes ON Player.player_api_id = Player_Attributes.player_api_id WHERE Player_Attributes.potential = (SELECT MAX(potential) FROM Player_Attributes);
SELECT COUNT(*)  FROM Player p  JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id  WHERE p.weight < 130 AND pa.preferred_foot = 'left';
SELECT DISTINCT T.team_short_name FROM Team T JOIN Team_Attributes TA ON T.team_api_id = TA.team_api_id WHERE TA.chanceCreationPassingClass = 'Risky';
SELECT pa.defensive_work_rate FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE p.player_name = 'David Wilson';
SELECT p.birthday FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE pa.overall_rating = (SELECT MAX(overall_rating) FROM Player_Attributes);
SELECT l.name FROM League l JOIN Country c ON l.country_id = c.id WHERE c.name = 'Netherlands';
SELECT AVG(m.home_team_goal) FROM Match m JOIN Country c ON m.country_id = c.id WHERE c.name = 'Poland' AND m.season = '2010/2011';
SELECT      (SELECT p.player_name       FROM Player p       JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id       WHERE p.height = (SELECT MAX(height) FROM Player)       ORDER BY pa.finishing DESC       LIMIT 1) AS tallest_player,     (SELECT p.player_name       FROM Player p       JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id       WHERE p.height = (SELECT MIN(height) FROM Player)       ORDER BY pa.finishing DESC       LIMIT 1) AS shortest_player;
SELECT player_name FROM Player WHERE height > 180;
SELECT COUNT(*) FROM Player WHERE strftime('%Y', birthday) > '1990';
SELECT COUNT(*)  FROM Player  WHERE player_name LIKE 'Adam %' AND weight > 170;
SELECT DISTINCT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE pa.overall_rating > 80   AND strftime('%Y', pa.date) BETWEEN '2008' AND '2010';
SELECT pa.potential FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE p.player_name = 'Aaron Doran';
SELECT player_name FROM Player JOIN Player_Attributes ON Player.player_api_id = Player_Attributes.player_api_id WHERE Player_Attributes.preferred_foot = 'left';
SELECT DISTINCT t.team_long_name FROM Team t JOIN Team_Attributes ta ON t.team_api_id = ta.team_api_id WHERE ta.buildUpPlaySpeedClass = 'Fast';
SELECT ta.buildUpPlayPassingClass FROM Team_Attributes ta JOIN Team t ON ta.team_api_id = t.team_api_id WHERE t.team_short_name = 'CLB';
SELECT T1.team_short_name FROM Team AS T1 JOIN Team_Attributes AS T2 ON T1.team_api_id = T2.team_api_id WHERE T2.buildUpPlayPassing > 70;
SELECT AVG(t2.overall_rating)  FROM Player AS t1  JOIN Player_Attributes AS t2 ON t1.player_api_id = t2.player_api_id  WHERE strftime('%Y', t2.date) >= '2010' AND strftime('%Y', t2.date) <= '2015' AND t1.height > 170;
SELECT player_name FROM Player WHERE height = (SELECT MIN(height) FROM Player);
SELECT c.name FROM Country c JOIN League l ON c.id = l.country_id WHERE l.name = 'Italy Serie A';
SELECT T.team_short_name FROM Team T JOIN Team_Attributes TA ON T.team_api_id = TA.team_api_id WHERE TA.buildUpPlaySpeed = 31 AND TA.buildUpPlayDribbling = 53 AND TA.buildUpPlayPassing = 32;
SELECT AVG(pa.overall_rating) FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE p.player_name = 'Aaron Doran';
SELECT COUNT(*)  FROM Match m JOIN League l ON m.league_id = l.id WHERE l.name = 'Germany 1. Bundesliga'    AND strftime('%Y-%m', m.date) BETWEEN '2008-08' AND '2008-10';
SELECT DISTINCT T1.team_short_name FROM Team AS T1 JOIN Match AS T2 ON T1.team_api_id = T2.home_team_api_id WHERE T2.home_team_goal = 10;
SELECT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE pa.potential = 61 AND pa.balance = (SELECT MAX(balance) FROM Player_Attributes WHERE potential = 61);
SELECT    AVG(CASE WHEN p.player_name = 'Abdou Diallo' THEN pa.ball_control END) -    AVG(CASE WHEN p.player_name = 'Aaron Appindangoye' THEN pa.ball_control END) FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name IN ('Abdou Diallo', 'Aaron Appindangoye');
SELECT team_long_name FROM Team WHERE team_short_name = 'GEN';
SELECT player_name FROM Player WHERE player_name IN ('Aaron Lennon', 'Abdelaziz Barrada') ORDER BY birthday ASC LIMIT 1;
SELECT player_name FROM Player WHERE height = (SELECT MAX(height) FROM Player);
SELECT COUNT(*)  FROM Player_Attributes  WHERE preferred_foot = 'left' AND attacking_work_rate = 'low';
SELECT c.name FROM League l JOIN Country c ON l.country_id = c.id WHERE l.name = 'Belgium Jupiler League';
SELECT League.name FROM League JOIN Country ON League.country_id = Country.id WHERE Country.name = 'Germany';
SELECT player_name FROM Player JOIN Player_Attributes ON Player.player_api_id = Player_Attributes.player_api_id WHERE Player_Attributes.overall_rating = (SELECT MAX(overall_rating) FROM Player_Attributes);
SELECT COUNT(DISTINCT p.id) FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE strftime('%Y', p.birthday) < '1986'   AND pa.defensive_work_rate = 'high';
SELECT player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE p.player_name IN ('Alexis', 'Ariel Borysiuk', 'Arouna Kone') ORDER BY pa.crossing DESC LIMIT 1;
SELECT pa.heading_accuracy FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE p.player_name = 'Ariel Borysiuk';
SELECT COUNT(*)  FROM Player p  JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id  WHERE p.height > 180 AND pa.volleys > 70;
SELECT DISTINCT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE pa.volleys > 70 AND pa.dribbling > 70;
SELECT COUNT(*)  FROM Match m JOIN Country c ON m.country_id = c.id WHERE c.name = 'Belgium' AND m.season = '2008/2009';
SELECT pa.long_passing FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.birthday = (SELECT MIN(birthday) FROM Player) LIMIT 1;
SELECT COUNT(*)  FROM `Match` m JOIN `League` l ON m.league_id = l.id WHERE l.name = 'Belgium Jupiler League'    AND SUBSTR(m.date, 1, 7) = '2009-04';
SELECT l.name FROM League l JOIN Match m ON l.id = m.league_id WHERE m.season = '2008/2009' GROUP BY l.name ORDER BY COUNT(*) DESC LIMIT 1;
SELECT AVG(T2.overall_rating) FROM Player AS T1 JOIN Player_Attributes AS T2 ON T1.player_api_id = T2.player_api_id WHERE strftime('%Y', T1.birthday) < '1986';
SELECT    ((SELECT pa.overall_rating      FROM Player_Attributes pa      JOIN Player p ON pa.player_api_id = p.player_api_id      WHERE p.player_name = 'Ariel Borysiuk') -     (SELECT pa.overall_rating      FROM Player_Attributes pa      JOIN Player p ON pa.player_api_id = p.player_api_id      WHERE p.player_name = 'Paulin Puel')) * 100.0 /    (SELECT pa.overall_rating     FROM Player_Attributes pa     JOIN Player p ON pa.player_api_id = p.player_api_id     WHERE p.player_name = 'Paulin Puel') AS percentage_difference
SELECT AVG(TA.buildUpPlaySpeed) FROM Team_Attributes TA JOIN Team T ON TA.team_api_id = T.team_api_id WHERE T.team_long_name = 'Heart of Midlothian';
SELECT AVG(T1.overall_rating) FROM Player_Attributes AS T1 JOIN Player AS T2 ON T1.player_api_id = T2.player_api_id WHERE T2.player_name = 'Pietro Marino';
SELECT SUM(T1.crossing)  FROM Player_Attributes AS T1  JOIN Player AS T2 ON T1.player_api_id = T2.player_api_id  WHERE T2.player_name = 'Aaron Lennox';
SELECT MAX(chanceCreationPassing), chanceCreationPassingClass FROM Team_Attributes JOIN Team ON Team_Attributes.team_api_id = Team.team_api_id WHERE Team.team_long_name = 'Ajax';
SELECT pa.preferred_foot FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE p.player_name = 'Abdou Diallo';
SELECT MAX(PA.overall_rating) FROM Player_Attributes PA JOIN Player P ON PA.player_api_id = P.player_api_id WHERE P.player_name = 'Dorlan Pabon';
SELECT AVG(m.away_team_goal) FROM Match m JOIN Team t ON m.away_team_api_id = t.team_api_id JOIN Country c ON m.country_id = c.id WHERE t.team_long_name = 'Parma' AND c.name = 'Italy';
SELECT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE pa.overall_rating = 77   AND pa.date LIKE '2016-06-23%' ORDER BY p.birthday ASC LIMIT 1;
SELECT pa.overall_rating FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Aaron Mooy' AND pa.date LIKE '2016-02-04%';
SELECT pa.potential FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Francesco Parravicini' AND pa.date = '2010-08-30 00:00:00';
SELECT pa.attacking_work_rate FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Francesco Migliore' AND pa.date LIKE '2015-05-01%';
SELECT pa.defensive_work_rate FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Kevin Berigaud' AND pa.date = '2013-02-22 00:00:00';
SELECT date FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Kevin Constant' ORDER BY pa.crossing DESC LIMIT 1;
SELECT `buildUpPlaySpeedClass`  FROM `Team_Attributes`  WHERE `team_api_id` = (     SELECT `team_api_id`      FROM `Team`      WHERE `team_long_name` = 'Willem II' )  AND `date` = '2012-02-22';
SELECT ta.buildUpPlayDribblingClass FROM Team_Attributes ta JOIN Team t ON ta.team_api_id = t.team_api_id WHERE t.team_short_name = 'LEI' AND ta.date = '2015-09-10 00:00:00';
SELECT ta.buildUpPlayPassingClass FROM Team_Attributes ta JOIN Team t ON ta.team_api_id = t.team_api_id WHERE t.team_long_name = 'FC Lorient' AND ta.date LIKE '2010-02-22%';
SELECT ta.chanceCreationPassingClass FROM Team_Attributes ta JOIN Team t ON ta.team_api_id = t.team_api_id WHERE t.team_long_name = 'PEC Zwolle' AND ta.date = '2013-09-20 00:00:00';
SELECT ta.chanceCreationCrossingClass FROM Team_Attributes ta JOIN Team t ON ta.team_api_id = t.team_api_id WHERE t.team_long_name = 'Hull City' AND ta.date = '2010-02-22 00:00:00';
SELECT ta.defenceAggressionClass FROM Team_Attributes ta JOIN Team t ON ta.team_api_id = t.team_api_id WHERE t.team_long_name = 'Hannover 96' AND ta.date LIKE '2015-09-10%';
SELECT AVG(T2.overall_rating)  FROM Player AS T1  JOIN Player_Attributes AS T2  ON T1.player_api_id = T2.player_api_id  WHERE T1.player_name = 'Marko Arnautovic'  AND SUBSTR(T2.date, 1, 10) BETWEEN '2007-02-22' AND '2016-04-21';
SELECT      ((pa1.overall_rating - pa2.overall_rating) * 100.0 / pa1.overall_rating) AS percentage FROM      Player p1 JOIN      Player_Attributes pa1 ON p1.player_api_id = pa1.player_api_id JOIN      Player p2 ON p2.player_name = 'Jordan Bowery' JOIN      Player_Attributes pa2 ON p2.player_api_id = pa2.player_api_id WHERE      p1.player_name = 'Landon Donovan'      AND pa1.date = (         SELECT MAX(date)          FROM Player_Attributes          WHERE player_api_id = p1.player_api_id          AND date <= '2013-07-12'     )     AND pa2.date = (         SELECT MAX(date)          FROM Player_Attributes          WHERE player_api_id = p2.player_api_id          AND date <= '2013-07-12'     );
SELECT player_name FROM Player WHERE height = (SELECT MAX(height) FROM Player);
SELECT player_api_id FROM Player ORDER BY weight DESC LIMIT 10;
SELECT player_name  FROM Player  WHERE CAST(strftime('%Y', 'now') AS INTEGER) - CAST(strftime('%Y', birthday) AS INTEGER) > 34;
SELECT COUNT(*)  FROM Match m JOIN Player p ON m.home_player_1 = p.player_api_id OR m.home_player_2 = p.player_api_id OR m.home_player_3 = p.player_api_id OR m.home_player_4 = p.player_api_id OR m.home_player_5 = p.player_api_id OR m.home_player_6 = p.player_api_id OR m.home_player_7 = p.player_api_id OR m.home_player_8 = p.player_api_id OR m.home_player_9 = p.player_api_id OR m.home_player_10 = p.player_api_id OR m.home_player_11 = p.player_api_id WHERE p.player_name = 'Aaron Lennon' AND m.home_team_goal IS NOT NULL;
SELECT SUM(m.away_team_goal)  FROM Match m  JOIN Player p1 ON m.away_player_1 = p1.player_api_id OR m.away_player_2 = p1.player_api_id OR m.away_player_3 = p1.player_api_id OR m.away_player_4 = p1.player_api_id OR m.away_player_5 = p1.player_api_id OR m.away_player_6 = p1.player_api_id OR m.away_player_7 = p1.player_api_id OR m.away_player_8 = p1.player_api_id OR m.away_player_9 = p1.player_api_id OR m.away_player_10 = p1.player_api_id OR m.away_player_11 = p1.player_api_id  JOIN Player p2 ON m.away_player_1 = p2.player_api_id OR m.away_player_2 = p2.player_api_id OR m.away_player_3 = p2.player_api_id OR m.away_player_4 = p2.player_api_id OR m.away_player_5 = p2.player_api_id OR m.away_player_6 = p2.player_api_id OR m.away_player_7 = p2.player_api_id OR m.away_player_8 = p2.player_api_id OR m.away_player_9 = p2.player_api_id OR m.away_player_10 = p2.player_api_id OR m.away_player_11 = p2.player_api_id  WHERE (p1.player_name = 'Daan Smith' OR p2.player_name = 'Daan Smith')    AND (p1.player_name = 'Filipe Ferreira' OR p2.player_name = 'Filipe Ferreira');
SELECT SUM(m.home_team_goal)  FROM Match m JOIN Player p ON m.home_player_1 = p.player_api_id OR m.home_player_2 = p.player_api_id OR m.home_player_3 = p.player_api_id OR m.home_player_4 = p.player_api_id OR m.home_player_5 = p.player_api_id OR m.home_player_6 = p.player_api_id OR m.home_player_7 = p.player_api_id OR m.home_player_8 = p.player_api_id OR m.home_player_9 = p.player_api_id OR m.home_player_10 = p.player_api_id OR m.home_player_11 = p.player_api_id WHERE strftime('%Y', 'now') - strftime('%Y', p.birthday) <= 30;
SELECT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE pa.overall_rating = (SELECT MAX(overall_rating) FROM Player_Attributes)
SELECT player_name FROM Player JOIN Player_Attributes ON Player.player_api_id = Player_Attributes.player_api_id WHERE Player_Attributes.potential = (SELECT MAX(potential) FROM Player_Attributes);
SELECT DISTINCT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE pa.attacking_work_rate = 'high';
SELECT player_name FROM Player JOIN Player_Attributes ON Player.player_api_id = Player_Attributes.player_api_id WHERE Player_Attributes.finishing = 1 ORDER BY (julianday('now') - julianday(Player.birthday)) DESC LIMIT 1;
SELECT p.player_name FROM Player p JOIN Match m ON p.player_api_id = m.home_player_1 OR p.player_api_id = m.away_player_1 JOIN Country c ON m.country_id = c.id WHERE c.name = 'Belgium';
SELECT DISTINCT 'Unknown' AS name FROM Player_Attributes pa WHERE pa.vision > 89;
SELECT c.name FROM Country c JOIN League l ON c.id = l.country_id JOIN Match m ON l.id = m.league_id JOIN Player p ON m.home_player_1 = p.player_api_id OR m.away_player_1 = p.player_api_id GROUP BY c.name ORDER BY AVG(p.weight) DESC LIMIT 1;
SELECT T1.team_long_name FROM Team AS T1 JOIN Team_Attributes AS T2 ON T1.team_api_id = T2.team_api_id WHERE T2.buildUpPlaySpeedClass = 'Slow';
SELECT T1.team_short_name FROM Team AS T1 JOIN Team_Attributes AS T2 ON T1.team_api_id = T2.team_api_id WHERE T2.chanceCreationPassingClass = 'Safe';
SELECT AVG(p.height) FROM Player p JOIN Match m ON p.player_api_id = m.home_player_1 OR p.player_api_id = m.away_player_1 JOIN Country c ON m.country_id = c.id WHERE c.name = 'Italy';
SELECT player_name FROM Player WHERE height > 180 ORDER BY player_name LIMIT 3;
SELECT COUNT(*)  FROM Player  WHERE player_name LIKE 'Aaron%' AND birthday > '1990-12-31 00:00:00';
SELECT    (SELECT jumping FROM Player_Attributes WHERE id = 6) -    (SELECT jumping FROM Player_Attributes WHERE id = 23) AS difference;
SELECT player_api_id FROM Player_Attributes WHERE potential = (SELECT MIN(potential) FROM Player_Attributes)   AND preferred_foot = 'right' ORDER BY id LIMIT 5;
SELECT COUNT(*)  FROM Player_Attributes  WHERE crossing = (SELECT MAX(crossing) FROM Player_Attributes)    AND preferred_foot = 'left';
SELECT CAST(COUNT(*) AS REAL) * 100 / (SELECT COUNT(*) FROM Player_Attributes)  FROM Player_Attributes  WHERE stamina > 80 AND strength > 80;
SELECT c.name FROM League l JOIN Country c ON l.country_id = c.id WHERE l.name = 'Poland Ekstraklasa';
SELECT m.home_team_goal, m.away_team_goal FROM Match m JOIN League l ON m.league_id = l.id WHERE m.date LIKE '2008-09-24%' AND l.name = 'Belgium Jupiler League';
SELECT pa.sprint_speed, pa.agility, pa.acceleration FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Alexis Blin';
SELECT ta.buildUpPlaySpeedClass FROM Team t JOIN Team_Attributes ta ON t.team_api_id = ta.team_api_id WHERE t.team_long_name = 'KSV Cercle Brugge';
SELECT COUNT(*)  FROM Match  WHERE season = '2015/2016'    AND league_id = (SELECT id FROM League WHERE name = 'Italy Serie A');
SELECT MAX(m.home_team_goal) FROM Match m JOIN League l ON m.league_id = l.id WHERE l.name = 'Netherlands Eredivisie';
SELECT pa.finishing, pa.curve FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE p.weight = (SELECT MAX(weight) FROM Player)
SELECT L.name FROM League L JOIN Match M ON L.id = M.league_id WHERE M.season = '2015/2016' GROUP BY L.name ORDER BY COUNT(M.id) DESC LIMIT 4;
SELECT t.team_long_name FROM Match m JOIN Team t ON m.away_team_api_id = t.team_api_id WHERE m.away_team_goal = (SELECT MAX(away_team_goal) FROM Match)
SELECT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE pa.overall_rating = (SELECT MAX(overall_rating) FROM Player_Attributes);
SELECT CAST(COUNT(CASE WHEN p.height < 180 AND pa.overall_rating > 70 THEN 1 END) AS REAL) * 100 / COUNT(*)  FROM Player p  JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id;
SELECT    CASE      WHEN COUNT(CASE WHEN SEX = 'M' AND Admission = '+' THEN 1 END) > COUNT(CASE WHEN SEX = 'M' AND Admission = '-' THEN 1 END) THEN 'in-patient'     ELSE 'outpatient'   END AS more_type,   (COUNT(CASE WHEN SEX = 'M' AND Admission = '+' THEN 1 END) * 100.0 / NULLIF(COUNT(CASE WHEN SEX = 'M' AND Admission = '-' THEN 1 END), 0)) - 100 AS deviation_percentage FROM Patient;
SELECT CAST(COUNT(CASE WHEN strftime('%Y', `Birthday`) > '1930' AND `SEX` = 'F' THEN 1 END) AS REAL) * 100 / COUNT(CASE WHEN `SEX` = 'F' THEN 1 END) FROM `Patient`;
SELECT CAST(COUNT(CASE WHEN `Admission` = '+' THEN 1 END) AS REAL) * 100 / COUNT(*)  FROM `Patient`  WHERE strftime('%Y', `Birthday`) BETWEEN '1930' AND '1940';
SELECT CAST(COUNT(CASE WHEN `Admission` = '+' THEN `ID` END) AS REAL) / COUNT(CASE WHEN `Admission` = '-' THEN `ID` END)  FROM `Patient`  WHERE `Diagnosis` = 'SLE';
SELECT      p.`Diagnosis`,     l.`Date` FROM      `Patient` p JOIN      `Laboratory` l ON p.`ID` = l.`ID` WHERE      p.`ID` = 30609;
SELECT      p.SEX,      p.Birthday,      e.`Examination Date`,      e.Symptoms  FROM      Patient p  JOIN      Examination e  ON      p.ID = e.ID  WHERE      p.ID = 163109;
SELECT DISTINCT p.ID, p.SEX, p.Birthday FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.LDH > 500;
SELECT E.ID, CAST(strftime('%Y', 'now') AS INTEGER) - CAST(strftime('%Y', P.Birthday) AS INTEGER) AS age FROM Examination E JOIN Patient P ON E.ID = P.ID WHERE E.RVVT = '+'
SELECT P.ID, P.SEX, P.Diagnosis FROM Patient P JOIN Examination E ON P.ID = E.ID WHERE E.Thrombosis = 2;
SELECT DISTINCT p.ID FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE strftime('%Y', p.Birthday) = '1937' AND l.`T-CHO` >= 250;
SELECT DISTINCT p.ID, p.SEX, p.Diagnosis FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.ALB < 3.5;
SELECT CAST(COUNT(CASE WHEN p.SEX = 'F' AND (l.TP < 6.0 OR l.TP > 8.5) THEN 1 END) AS REAL) * 100 / COUNT(*)  FROM Patient p  JOIN Laboratory l ON p.ID = l.ID;
SELECT AVG(e.`aCL IgG`) FROM `Examination` e JOIN `Patient` p ON e.`ID` = p.`ID` WHERE p.`Admission` = '+'    AND strftime('%Y', 'now') - strftime('%Y', p.`Birthday`) >= 50;
SELECT COUNT(*)  FROM `Patient`  WHERE `SEX` = 'F'    AND strftime('%Y', `Description`) = '1997'    AND `Admission` = '-';
SELECT MIN(CAST(strftime('%Y', `First Date`) AS INTEGER) - CAST(strftime('%Y', `Birthday`) AS INTEGER)) FROM `Patient` WHERE `First Date` IS NOT NULL AND `Birthday` IS NOT NULL;
SELECT COUNT(*)  FROM Patient p  JOIN Examination e ON p.ID = e.ID  WHERE p.SEX = 'F'  AND e.Thrombosis = 1  AND strftime('%Y', e.`Examination Date`) = '1997';
SELECT MAX(strftime('%Y', p.Birthday)) - MIN(strftime('%Y', p.Birthday)) FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.TG >= 200;
SELECT e.`Symptoms`, e.`Diagnosis` FROM `Examination` e JOIN `Patient` p ON e.`ID` = p.`ID` WHERE p.`ID` = (     SELECT `ID`     FROM `Patient`     WHERE `Birthday` = (SELECT MAX(`Birthday`) FROM `Patient`) ) AND e.`Symptoms` IS NOT NULL;
SELECT COUNT(DISTINCT p.ID) / 12.0 FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.SEX = 'M' AND l.Date BETWEEN '1998-01-01' AND '1998-12-31';
SELECT      l.`Date` AS latest_lab_date,     CAST(strftime('%Y', p.`First Date`) AS INTEGER) - CAST(strftime('%Y', p.`Birthday`) AS INTEGER) AS age_at_first_admission FROM      `Patient` p JOIN      `Laboratory` l ON p.`ID` = l.`ID` WHERE      p.`Diagnosis` = 'SJS' ORDER BY      p.`Birthday` ASC, l.`Date` DESC LIMIT 1;
SELECT CAST(SUM(CASE WHEN p.SEX = 'M' AND l.UA <= 8.0 THEN 1 ELSE 0 END) AS REAL) / SUM(CASE WHEN p.SEX = 'F' AND l.UA <= 6.5 THEN 1 ELSE 0 END)  FROM Patient p  JOIN Laboratory l ON p.ID = l.ID;
SELECT COUNT(*)  FROM `Patient` p  JOIN `Examination` e ON p.`ID` = e.`ID`  WHERE e.`Examination Date` IS NOT NULL    AND p.`First Date` IS NOT NULL    AND (strftime('%Y', e.`Examination Date`) - strftime('%Y', p.`First Date`)) >= 1;
SELECT COUNT(*)  FROM `Examination` e  JOIN `Patient` p ON e.`ID` = p.`ID`  WHERE strftime('%Y', p.`Birthday`) < '1972'  AND strftime('%Y', e.`Examination Date`) BETWEEN '1990' AND '1993';
SELECT COUNT(*)  FROM Patient p  JOIN Laboratory l ON p.ID = l.ID  WHERE p.SEX = 'M' AND l.`T-BIL` >= 2.0;
SELECT `Diagnosis` FROM `Examination` WHERE `Examination Date` BETWEEN '1985-01-01' AND '1995-12-31' GROUP BY `Diagnosis` ORDER BY COUNT(*) DESC LIMIT 1;
SELECT AVG(1999 - CAST(strftime('%Y', `Birthday`) AS INTEGER))  FROM `Patient` AS p  JOIN `Laboratory` AS l ON p.`ID` = l.`ID`  WHERE l.`Date` BETWEEN '1991-10-01' AND '1991-10-30';
SELECT      CAST(strftime('%Y', e.`Examination Date`) AS INTEGER) - CAST(strftime('%Y', p.`Birthday`) AS INTEGER) AS age,     p.`Diagnosis` FROM `Examination` e JOIN `Patient` p ON e.`ID` = p.`ID` JOIN `Laboratory` l ON e.`ID` = l.`ID` WHERE l.`HGB` = (SELECT MAX(`HGB`) FROM `Laboratory`);
SELECT `ANA` FROM `Examination` WHERE `ID` = 3605340 AND `Examination Date` = '1996-12-02';
SELECT `T-CHO` < 250 AS is_normal FROM `Laboratory` WHERE `ID` = 2927464 AND `Date` = '1995-09-04';
SELECT p.SEX FROM Patient p WHERE p.Diagnosis = 'AORTITIS' ORDER BY p.ID LIMIT 1;
SELECT `aCL IgM`  FROM `Examination`  WHERE `ID` = (     SELECT `ID`      FROM `Patient`      WHERE `Diagnosis` = 'SLE' AND `Description` = '1994-02-19' )  AND `Examination Date` = '1993-11-12';
SELECT p.SEX FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.Date = '1992-06-12' AND l.GPT = 9;
SELECT CAST(strftime('%Y', '1991-10-21') AS INTEGER) - CAST(strftime('%Y', p.`Birthday`) AS INTEGER) FROM `Laboratory` l JOIN `Patient` p ON l.`ID` = p.`ID` WHERE l.`UA` = 8.4 AND l.`Date` = '1991-10-21';
SELECT COUNT(*)  FROM `Laboratory`  WHERE `ID` = (     SELECT `ID`      FROM `Patient`      WHERE `First Date` = '1991-06-13' AND `Diagnosis` = 'SJS' )  AND strftime('%Y', `Date`) = '1995';
SELECT p.`Diagnosis` FROM `Patient` p JOIN `Examination` e ON p.`ID` = e.`ID` WHERE e.`Diagnosis` = 'SLE' AND e.`Examination Date` = '1997-01-27';
SELECT e.`Symptoms` FROM `Examination` e JOIN `Patient` p ON e.`ID` = p.`ID` WHERE p.`Birthday` = '1959-03-01' AND e.`Examination Date` = '1993-09-27';
SELECT    (SUM(CASE WHEN `Date` LIKE '1981-11-%' THEN `T-CHO` END) -     SUM(CASE WHEN `Date` LIKE '1981-12-%' THEN `T-CHO` END)) AS decrease_rate FROM `Laboratory` AS L JOIN `Patient` AS P ON L.`ID` = P.`ID` WHERE P.`Birthday` = '1959-02-18';
SELECT DISTINCT p.ID FROM Patient p JOIN Examination e ON p.ID = e.ID WHERE p.Diagnosis LIKE '%Behcet%'    AND e.`Examination Date` >= '1997-01-01'    AND e.`Examination Date` <= '1997-12-31';
SELECT DISTINCT T2.ID FROM Examination AS T1 JOIN Laboratory AS T2 ON T1.ID = T2.ID WHERE T1.`Examination Date` BETWEEN '1987-07-06' AND '1996-01-31'   AND T2.GPT > 30   AND T2.ALB < 4;
SELECT COUNT(*) AS count, ID FROM Patient WHERE SEX = 'F' AND strftime('%Y', Birthday) = '1964' AND Admission = '+' GROUP BY ID;
SELECT COUNT(*)  FROM `Examination`  WHERE `Thrombosis` = 2    AND `ANA Pattern` = 'S'    AND `aCL IgM` > (SELECT AVG(`aCL IgM`) * 1.2 FROM `Examination`);
SELECT      CAST(SUM(CASE WHEN `UA` <= 6.5 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*)  FROM `Laboratory`  WHERE `U-PRO` > 0 AND `U-PRO` < 30;
SELECT CAST(SUM(CASE WHEN `Diagnosis` = 'BEHCET' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*)  FROM `Patient`  WHERE `SEX` = 'M' AND strftime('%Y', `First Date`) = '1981';
SELECT DISTINCT p.ID FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Admission = '-'   AND l.Date LIKE '1991-10%'   AND l.`T-BIL` < 2.0;
SELECT COUNT(*)  FROM Patient p  JOIN Examination e ON p.ID = e.ID  WHERE e.`ANA Pattern` != 'P'    AND p.SEX = 'F'    AND p.Birthday >= '1980-01-01'    AND p.Birthday <= '1989-12-31';
SELECT p.SEX FROM Patient p JOIN Examination e ON p.ID = e.ID JOIN Laboratory l ON p.ID = l.ID WHERE e.Diagnosis = 'PSS'    AND l.CRP = '2+'    AND l.CRE = 1    AND l.LDH = 123;
SELECT AVG(l.`ALB`) FROM `Patient` p JOIN `Laboratory` l ON p.`ID` = l.`ID` WHERE p.`SEX` = 'F'    AND l.`PLT` > 400    AND p.`Diagnosis` = 'SLE';
SELECT MAX(`Symptoms`) FROM `Examination` WHERE `Diagnosis` = 'SLE';
SELECT `Description`, `Diagnosis` FROM `Patient` WHERE `ID` = 48473;
SELECT COUNT(*)  FROM `Patient`  WHERE `SEX` = 'F' AND `Diagnosis` = 'APS';
SELECT COUNT(*)  FROM `Laboratory`  WHERE strftime('%Y', `Date`) = '1997' AND (`TP` <= 6 OR `TP` >= 8.5);
SELECT CAST(SUM(CASE WHEN e.`Symptoms` LIKE '%thrombocytopenia%' AND p.`Diagnosis` = 'SLE' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*)  FROM `Examination` e  JOIN `Patient` p ON e.`ID` = p.`ID`;
SELECT CAST(SUM(CASE WHEN `SEX` = 'F' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*)  FROM `Patient`  WHERE strftime('%Y', `Birthday`) = '1980' AND `Diagnosis` = 'RA';
SELECT COUNT(*)  FROM Patient p  JOIN Examination e ON p.ID = e.ID  WHERE p.SEX = 'M'    AND e.`Examination Date` BETWEEN '1995-01-01' AND '1997-12-31'    AND p.Diagnosis = 'Behcet'    AND p.Admission = '-';
SELECT COUNT(*)  FROM Patient p  JOIN Laboratory l ON p.ID = l.ID  WHERE p.SEX = 'F' AND l.WBC < 3.5;
SELECT julianday(e.`Examination Date`) - julianday(p.`First Date`)  FROM `Examination` AS e  JOIN `Patient` AS p ON e.`ID` = p.`ID`  WHERE p.`ID` = 821298;
SELECT      CASE          WHEN l.UA > 8.0 AND p.SEX = 'M' THEN 'Yes'         WHEN l.UA > 6.5 AND p.SEX = 'F' THEN 'Yes'         ELSE 'No'     END AS within_normal_range FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.ID = 57266;
SELECT `Date` FROM `Laboratory` WHERE `ID` = 48473 AND `GOT` >= 60;
SELECT DISTINCT p.ID, p.SEX, p.Birthday FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.GOT < 60 AND strftime('%Y', l.Date) = '1994';
SELECT DISTINCT p.ID FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.SEX = 'M' AND l.GPT >= 60;
SELECT p.`Diagnosis` FROM `Patient` p JOIN `Laboratory` l ON p.`ID` = l.`ID` WHERE l.`GPT` > 60 ORDER BY p.`Birthday` ASC;
SELECT AVG(LDH) FROM `Laboratory` WHERE LDH < 500;
SELECT p.ID, CAST(strftime('%Y', 'now') AS INTEGER) - CAST(strftime('%Y', p.Birthday) AS INTEGER) AS age FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.LDH BETWEEN 600 AND 800;
SELECT DISTINCT p.Admission FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.ALP < 300;
SELECT p.ID, CASE WHEN l.ALP IS NULL THEN 'unknown' WHEN l.ALP < 300 THEN 'yes' ELSE 'no' END AS is_ALP_normal FROM Patient p LEFT JOIN Laboratory l ON p.ID = l.ID WHERE p.Birthday = '1982-04-01';
SELECT DISTINCT p.ID, p.SEX, p.Birthday FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.TP < 6.0;
SELECT `TP` - 8.5 FROM `Laboratory` AS L JOIN `Patient` AS P ON L.`ID` = P.`ID` WHERE P.`SEX` = 'F' AND L.`TP` > 8.5;
SELECT DISTINCT p.* FROM Patient p WHERE p.SEX = 'M'   AND EXISTS (     SELECT 1      FROM Laboratory l      WHERE l.ID = p.ID        AND l.ALB IS NOT NULL        AND (l.ALB <= 3.5 OR l.ALB >= 5.5)   ) ORDER BY p.Birthday DESC;
SELECT      p.ID,     CASE          WHEN l.ALB BETWEEN 3.5 AND 5.5 THEN 'Within normal range'         ELSE 'Outside normal range'     END AS albumin_status FROM      Patient p JOIN      Laboratory l ON p.ID = l.ID WHERE      strftime('%Y', p.Birthday) = '1982';
SELECT      CAST(SUM(CASE WHEN l.UA > 6.5 AND p.SEX = 'F' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*)  FROM Patient p  JOIN Laboratory l ON p.ID = l.ID;
SELECT AVG(l.UA)  FROM Laboratory l JOIN Patient p ON l.ID = p.ID WHERE (p.SEX = 'M' AND l.UA < 8.0) OR (p.SEX = 'F' AND l.UA < 6.5) AND l.Date = (     SELECT MAX(l2.Date)      FROM Laboratory l2      WHERE l2.ID = l.ID );
SELECT DISTINCT p.ID, p.SEX, p.Birthday FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.UN = 29;
SELECT p.ID, p.SEX, p.Birthday FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Diagnosis LIKE '%RA%' AND l.UN < 30;
SELECT COUNT(*)  FROM Patient p  JOIN Laboratory l ON p.ID = l.ID  WHERE p.SEX = 'M' AND l.CRE >= 1.5;
SELECT SUM(CASE WHEN p.SEX = 'M' THEN 1 ELSE 0 END) > SUM(CASE WHEN p.SEX = 'F' THEN 1 ELSE 0 END) AS result FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.CRE >= 1.5;
SELECT p.ID, p.SEX, p.Birthday FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.`T-BIL` = (SELECT MAX(`T-BIL`) FROM Laboratory);
SELECT GROUP_CONCAT(DISTINCT p.ID), p.SEX FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.`T-BIL` >= 2.0 GROUP BY p.SEX;
SELECT p.ID, l.`T-CHO` FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Birthday = (SELECT MIN(Birthday) FROM Patient) ORDER BY l.`T-CHO` DESC LIMIT 1;
SELECT AVG(strftime('%Y', 'now') - strftime('%Y', p.Birthday))  FROM Patient p  JOIN Laboratory l ON p.ID = l.ID  WHERE p.SEX = 'M' AND l.`T-CHO` >= 250;
SELECT p.ID, p.Diagnosis FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.TG > 300;
SELECT COUNT(DISTINCT p.ID) FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.TG >= 200   AND (strftime('%Y', 'now') - strftime('%Y', p.Birthday)) > 50;
SELECT DISTINCT T1.ID FROM Patient AS T1 JOIN Laboratory AS T2 ON T1.ID = T2.ID WHERE T1.Admission = '-' AND T2.CPK < 250;
SELECT COUNT(DISTINCT T1.ID)  FROM Patient AS T1  JOIN Laboratory AS T2  ON T1.ID = T2.ID  WHERE strftime('%Y', T1.Birthday) BETWEEN '1936' AND '1956'  AND T1.SEX = 'M'  AND T2.CPK >= 250;
SELECT p.ID, p.SEX, CAST(strftime('%Y', 'now') AS INTEGER) - CAST(strftime('%Y', p.Birthday) AS INTEGER) AS age FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.GLU >= 180 AND l.`T-CHO` < 250;
SELECT P.ID, L.GLU FROM Patient P JOIN Laboratory L ON P.ID = L.ID WHERE strftime('%Y', P.Description) = '1991' AND L.GLU < 180;
SELECT p.ID, p.SEX, p.Birthday FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.WBC <= 3.5 OR l.WBC >= 9.0 ORDER BY p.SEX, (strftime('%Y', 'now') - strftime('%Y', p.Birthday)) ASC;
SELECT p.ID, CAST(strftime('%Y', 'now') AS INTEGER) - CAST(strftime('%Y', p.Birthday) AS INTEGER) AS age, p.Diagnosis FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.RBC < 3.5;
SELECT      p.ID,     p.Admission FROM      Patient p JOIN      Laboratory l ON p.ID = l.ID WHERE      p.SEX = 'F'      AND (strftime('%Y', 'now') - strftime('%Y', p.Birthday)) >= 50     AND (l.RBC <= 3.5 OR l.RBC >= 6.0);
SELECT DISTINCT P.ID, P.SEX FROM Patient P JOIN Laboratory L ON P.ID = L.ID WHERE P.Admission = '-' AND L.HGB < 10;
SELECT p.ID, p.SEX FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Diagnosis = 'SLE' AND l.HGB > 10 AND l.HGB < 17 ORDER BY p.Birthday ASC LIMIT 1;
SELECT p.ID, CAST(strftime('%Y', 'now') AS INTEGER) - CAST(strftime('%Y', p.Birthday) AS INTEGER) AS age FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.HCT >= 52 GROUP BY p.ID HAVING COUNT(l.ID) >= 2;
SELECT AVG(HCT) FROM Laboratory WHERE Date LIKE '1991%' AND HCT < 29;
SELECT    SUM(CASE WHEN `PLT` < 100 THEN 1 ELSE 0 END) AS lower_than_normal,   SUM(CASE WHEN `PLT` > 400 THEN 1 ELSE 0 END) AS higher_than_normal,   SUM(CASE WHEN `PLT` < 100 THEN 1 ELSE 0 END) - SUM(CASE WHEN `PLT` > 400 THEN 1 ELSE 0 END) AS difference FROM `Laboratory` WHERE `PLT` IS NOT NULL AND (`PLT` < 100 OR `PLT` > 400);
SELECT P.ID, P.SEX, P.Birthday FROM Patient P JOIN Laboratory L ON P.ID = L.ID WHERE strftime('%Y', L.Date) = '1984'   AND CAST(strftime('%Y', 'now') AS INTEGER) - CAST(strftime('%Y', P.Birthday) AS INTEGER) < 50   AND L.PLT BETWEEN 100 AND 400;
SELECT CAST(SUM(CASE WHEN p.SEX = 'F' AND l.PT >= 14 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*)  FROM Patient p  JOIN Laboratory l ON p.ID = l.ID  WHERE strftime('%Y', 'now') - strftime('%Y', p.Birthday) > 55 AND l.PT IS NOT NULL;
SELECT DISTINCT p.ID FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE strftime('%Y', p.`First Date`) > '1992' AND l.PT < 14;
SELECT COUNT(*)  FROM `Examination` AS e JOIN `Laboratory` AS l ON e.`ID` = l.`ID` WHERE e.`Examination Date` > '1997-01-01' AND l.`APTT` < 45;
SELECT COUNT(DISTINCT e.ID) FROM Examination e JOIN Laboratory l ON e.ID = l.ID WHERE l.APTT > 45 AND e.Thrombosis = 0;
SELECT COUNT(DISTINCT p.ID) FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.SEX = 'M' AND l.WBC > 3.5 AND l.WBC < 9.0 AND (l.FG <= 150 OR l.FG >= 450);
SELECT COUNT(DISTINCT p.ID) FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Birthday > '1980-01-01' AND (l.FG < 150 OR l.FG > 450);
SELECT DISTINCT p.`Diagnosis` FROM `Patient` p JOIN `Laboratory` l ON p.`ID` = l.`ID` WHERE l.`U-PRO` >= 30;
SELECT p.ID FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.`U-PRO` > 0 AND l.`U-PRO` < 30 AND p.Diagnosis = 'SLE';
SELECT COUNT(DISTINCT `ID`) FROM `Laboratory` WHERE `IGG` >= 2000;
SELECT COUNT(*)  FROM `Examination` AS e  JOIN `Laboratory` AS l ON e.ID = l.ID  WHERE l.IGG > 900 AND l.IGG < 2000 AND e.Symptoms IS NOT NULL;
SELECT p.`Diagnosis` FROM `Patient` p JOIN `Laboratory` l ON p.`ID` = l.`ID` WHERE l.`IGA` BETWEEN 80 AND 500 ORDER BY l.`IGA` DESC LIMIT 1;
SELECT COUNT(*)  FROM `Patient` p  JOIN `Laboratory` l ON p.`ID` = l.`ID`  WHERE l.`IGA` > 80 AND l.`IGA` < 500 AND strftime('%Y', p.`First Date`) >= '1990';
SELECT `Diagnosis` FROM `Patient` p JOIN `Laboratory` l ON p.`ID` = l.`ID` WHERE l.`IGM` <= 40 OR l.`IGM` >= 400 GROUP BY `Diagnosis` ORDER BY COUNT(*) DESC LIMIT 1;
SELECT COUNT(*)  FROM Patient p  JOIN Laboratory l ON p.ID = l.ID  WHERE l.CRP = '+' AND p.Description IS NULL;
SELECT COUNT(*)  FROM Patient p  JOIN Laboratory l ON p.ID = l.ID  WHERE l.CRE >= 1.5 AND (strftime('%Y', 'now') - strftime('%Y', p.Birthday)) < 70    AND (strftime('%m-%d', 'now') >= strftime('%m-%d', p.Birthday) OR strftime('%m-%d', 'now') < strftime('%m-%d', p.Birthday) AND (strftime('%Y', 'now') - strftime('%Y', p.Birthday)) < 70);
SELECT COUNT(DISTINCT P.ID) FROM Patient P JOIN Examination E ON P.ID = E.ID JOIN Laboratory L ON P.ID = L.ID WHERE L.RA IN ('-', '+-') AND E.KCT = '+';
SELECT p.`Diagnosis` FROM `Patient` p JOIN `Laboratory` l ON p.`ID` = l.`ID` WHERE strftime('%Y', p.`Birthday`) >= '1985' AND l.`RA` IN ('-', '+-');
SELECT P.ID FROM Patient P JOIN Laboratory L ON P.ID = L.ID WHERE CAST(L.RF AS REAL) < 20    AND (strftime('%Y', 'now') - strftime('%Y', P.Birthday))        - (strftime('%m-%d', 'now') < strftime('%m-%d', P.Birthday)) > 60;
SELECT COUNT(*)  FROM Patient p  JOIN Examination e ON p.ID = e.ID  JOIN Laboratory l ON p.ID = l.ID  WHERE l.RF < 20 AND e.Thrombosis = 0;
SELECT COUNT(DISTINCT T1.ID) FROM Patient AS T1 JOIN Examination AS T2 ON T1.ID = T2.ID JOIN Laboratory AS T3 ON T1.ID = T3.ID WHERE T3.C3 > 35 AND T2.`ANA Pattern` = 'P';
SELECT e.ID FROM Examination e JOIN Laboratory l ON e.ID = l.ID WHERE l.HCT NOT BETWEEN 29 AND 52 ORDER BY e.`aCL IgA` DESC LIMIT 1;
SELECT COUNT(DISTINCT e.ID) FROM Examination e JOIN Laboratory l ON e.ID = l.ID WHERE e.Thrombosis = 1 AND l.C4 > 10;
SELECT COUNT(DISTINCT T1.ID) FROM Patient AS T1 JOIN Laboratory AS T2 ON T1.ID = T2.ID WHERE T2.RNP IN ('-', '+-') AND T1.Admission = '+';
SELECT MAX(p.Birthday)  FROM Patient p  JOIN Laboratory l ON p.ID = l.ID  WHERE l.RNP NOT IN ('-', '+-');
SELECT COUNT(*)  FROM Patient p JOIN Examination e ON p.ID = e.ID JOIN Laboratory l ON p.ID = l.ID WHERE l.SM IN ('-', '0') AND e.Thrombosis = 0;
SELECT p.`ID` FROM `Laboratory` l JOIN `Patient` p ON l.`ID` = p.`ID` WHERE l.`SM` NOT IN ('negative', '0') ORDER BY p.`Birthday` DESC LIMIT 3;
SELECT E.ID FROM Examination E JOIN Laboratory L ON E.ID = L.ID WHERE E.`Examination Date` > '1997-01-01'   AND L.SC170 IN ('negative', '0');
SELECT COUNT(DISTINCT T1.ID) FROM Patient AS T1 JOIN Examination AS T2 ON T1.ID = T2.ID JOIN Laboratory AS T3 ON T1.ID = T3.ID WHERE T3.SC170 IN ('negative', '0')   AND T1.SEX = 'F'   AND T2.Symptoms IS NULL;
SELECT COUNT(DISTINCT T1.ID)  FROM Patient AS T1  JOIN Laboratory AS T2 ON T1.ID = T2.ID  WHERE T2.SSA IN ('-', '+-')  AND strftime('%Y', T1.`First Date`) < '2000';
SELECT `ID`  FROM `Laboratory`  WHERE `SSA` NOT IN ('negative', '0')  ORDER BY `ID`  LIMIT 1;
SELECT COUNT(DISTINCT e.ID) FROM Examination e JOIN Patient p ON e.ID = p.ID JOIN Laboratory l ON e.ID = l.ID WHERE l.`SSB` IN ('-', '+-') AND p.`Diagnosis` = 'SLE';
SELECT COUNT(DISTINCT e.ID) FROM Examination e JOIN Laboratory l ON e.ID = l.ID WHERE l.SSB IN ('negative', '0') AND e.Symptoms IS NOT NULL;
SELECT COUNT(DISTINCT p.ID) FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.CENTROMEA IN ('-', '+-')    AND l.SSB IN ('-', '+-')    AND p.SEX = 'M';
SELECT DISTINCT p.`Diagnosis` FROM `Patient` p JOIN `Laboratory` l ON p.`ID` = l.`ID` WHERE l.`DNA` >= 8;
SELECT COUNT(DISTINCT T1.ID)  FROM Patient AS T1  JOIN Laboratory AS T2 ON T1.ID = T2.ID  WHERE T2.DNA < 8 AND T1.Description IS NULL;
SELECT COUNT(*)  FROM Patient p  JOIN Laboratory l ON p.ID = l.ID  WHERE l.IGG > 900 AND l.IGG < 2000 AND p.Admission = '+';
SELECT CAST(COUNT(CASE WHEN l.GOT >= 60 AND p.Diagnosis = 'SLE' THEN 1 END) AS REAL) * 100 / COUNT(CASE WHEN l.GOT >= 60 THEN 1 END) FROM Patient p JOIN Laboratory l ON p.ID = l.ID;
SELECT COUNT(*)  FROM Patient p  JOIN Laboratory l ON p.ID = l.ID  WHERE p.SEX = 'M' AND l.GOT < 60;
SELECT MAX(p.`Birthday`) FROM `Patient` p JOIN `Laboratory` l ON p.`ID` = l.`ID` WHERE l.`GOT` >= 60;
SELECT `Birthday`  FROM `Patient` AS p  JOIN `Laboratory` AS l ON p.`ID` = l.`ID`  WHERE l.`GPT` < 60  ORDER BY l.`GPT` DESC  LIMIT 3;
SELECT COUNT(*)  FROM Patient  WHERE ID IN (     SELECT ID      FROM Laboratory      WHERE GOT < 60 )  AND SEX = 'M';
SELECT MIN(`First Date`)  FROM `Patient`  WHERE `ID` IN (     SELECT `ID`      FROM `Laboratory`      WHERE `LDH` < 500      ORDER BY `LDH` DESC      LIMIT 1 );
SELECT MAX(l.`Date`)  FROM `Laboratory` l  JOIN `Patient` p ON l.`ID` = p.`ID`  WHERE p.`ID` = (SELECT `ID` FROM `Patient` WHERE `First Date` = (SELECT MAX(`First Date`) FROM `Patient`))  AND l.`LDH` >= 500;
SELECT COUNT(*)  FROM Patient p  JOIN Laboratory l ON p.ID = l.ID  WHERE l.ALP >= 300 AND p.Admission = '+'
SELECT COUNT(*)  FROM Patient p  JOIN Laboratory l ON p.ID = l.ID  WHERE p.Admission = '-' AND l.ALP < 300;
SELECT DISTINCT p.`Diagnosis` FROM `Patient` p JOIN `Laboratory` l ON p.`ID` = l.`ID` WHERE l.`TP` < 6.0;
SELECT COUNT(*)  FROM Patient p  JOIN Laboratory l ON p.ID = l.ID  WHERE p.Diagnosis = 'SJS' AND l.TP > 6.0 AND l.TP < 8.5;
SELECT `Examination Date`  FROM `Examination`  WHERE `ID` = (     SELECT `ID`      FROM `Laboratory`      WHERE `ALB` BETWEEN 3.5 AND 5.5      ORDER BY `ALB` DESC      LIMIT 1 );
SELECT COUNT(*)  FROM Patient p  JOIN Laboratory l ON p.ID = l.ID  WHERE p.SEX = 'M' AND l.ALB > 3.5 AND l.ALB < 5.5 AND l.TP BETWEEN 6.0 AND 8.5;
SELECT e.`aCL IgG`, e.`aCL IgM`, e.`aCL IgA` FROM `Examination` e JOIN `Patient` p ON e.`ID` = p.`ID` JOIN `Laboratory` l ON e.`ID` = l.`ID` WHERE p.`SEX` = 'F' AND l.`UA` > 6.50 ORDER BY l.`UA` DESC LIMIT 1;
SELECT MAX(e.ANA)  FROM Examination e  JOIN Laboratory l ON e.ID = l.ID  WHERE l.CRE < 1.5;
SELECT e.ID FROM Examination e JOIN Laboratory l ON e.ID = l.ID WHERE l.CRE < 1.5 AND e.`aCL IgA` = (SELECT MAX(`aCL IgA`) FROM Examination);
SELECT COUNT(*)  FROM Examination e  JOIN Laboratory l ON e.ID = l.ID  WHERE l.`T-BIL` >= 2.0  AND e.`ANA Pattern` LIKE '%P%';
SELECT e.`ANA` FROM `Examination` e JOIN `Laboratory` l ON e.`ID` = l.`ID` WHERE l.`T-BIL` IS NOT NULL AND l.`T-BIL` < 2.0 ORDER BY l.`T-BIL` DESC LIMIT 1;
