SELECT SUBSTR(y.Date, 1, 4) AS year FROM yearmonth y JOIN customers c ON y.CustomerID = c.CustomerID WHERE c.Currency = 'EUR' GROUP BY SUBSTR(y.Date, 1, 4) ORDER BY SUM(y.Consumption) DESC LIMIT 1;
SELECT c.Segment FROM customers c JOIN yearmonth y ON c.CustomerID = y.CustomerID GROUP BY c.Segment ORDER BY SUM(y.Consumption) ASC LIMIT 1;
SELECT SUBSTR(Date, 1, 4) AS Year FROM yearmonth JOIN customers ON yearmonth.CustomerID = customers.CustomerID WHERE customers.Currency = 'CZK' GROUP BY SUBSTR(Date, 1, 4) ORDER BY SUM(yearmonth.Consumption) DESC LIMIT 1;
SELECT SUBSTR(y.Date, 5, 2) AS month FROM yearmonth y JOIN customers c ON y.CustomerID = c.CustomerID WHERE c.Segment = 'SME' AND y.Date BETWEEN '201301' AND '201312' ORDER BY y.Consumption DESC LIMIT 1;
SELECT    (SELECT AVG(Consumption) FROM yearmonth y JOIN customers c ON y.CustomerID = c.CustomerID WHERE c.Segment = 'SME' AND y.Date LIKE '2013%') -    (SELECT AVG(Consumption) FROM yearmonth y JOIN customers c ON y.CustomerID = c.CustomerID WHERE c.Segment = 'LAM' AND y.Date LIKE '2013%') AS SME_LAM_Diff,   (SELECT AVG(Consumption) FROM yearmonth y JOIN customers c ON y.CustomerID = c.CustomerID WHERE c.Segment = 'LAM' AND y.Date LIKE '2013%') -    (SELECT AVG(Consumption) FROM yearmonth y JOIN customers c ON y.CustomerID = c.CustomerID WHERE c.Segment = 'KAM' AND y.Date LIKE '2013%') AS LAM_KAM_Diff,   (SELECT AVG(Consumption) FROM yearmonth y JOIN customers c ON y.CustomerID = c.CustomerID WHERE c.Segment = 'KAM' AND y.Date LIKE '2013%') -    (SELECT AVG(Consumption) FROM yearmonth y JOIN customers c ON y.CustomerID = c.CustomerID WHERE c.Segment = 'SME' AND y.Date LIKE '2013%') AS KAM_SME_Diff;
WITH consumption_by_segment_year AS (     SELECT          c.Segment,         SUM(CASE WHEN SUBSTR(ym.Date, 1, 4) = '2012' THEN ym.Consumption ELSE 0 END) AS consumption_2012,         SUM(CASE WHEN SUBSTR(ym.Date, 1, 4) = '2013' THEN ym.Consumption ELSE 0 END) AS consumption_2013     FROM customers c     INNER JOIN yearmonth ym ON c.CustomerID = ym.CustomerID     WHERE c.Currency = 'EUR' AND c.Segment IN ('SME', 'LAM', 'KAM')     GROUP BY c.Segment ), percentage_change AS (     SELECT          Segment,         CASE              WHEN consumption_2012 = 0 THEN NULL             ELSE ((consumption_2013 - consumption_2012) / consumption_2013) * 100         END AS percentage_increase     FROM consumption_by_segment_year ) SELECT      MAX(percentage_increase) AS biggest_percentage_increase,     MIN(percentage_increase) AS lowest_percentage_increase FROM percentage_change;
